        g.gain.setValueAtTime(0.0001, t0);
        g.gain.exponentialRampToValueAtTime(0.35, t0 + 0.15);
        g.gain.exponentialRampToValueAtTime(0.0001, t0 + 2.2);
        const p = actx.createStereoPanner();
