// ===========================================================================
// FLAVOR SYSTEMS: wakes, weather, currents, mirrors, territories, recipes
// ===========================================================================
const coloredWakes = [];
const currentLanes = [];
const petEchoQueue = [];
const weatherParticles = [];
let weatherMood = null; // { kind, t, life, pitchMul, aggressionMul }
let weatherTimer = 18;
let pendingGlassRain = 0; // hard pond splashes bleed into window mode
let glassRainBurst = null; // brief rain overlay while still in pond
let giantBedReveal = 0; // 0..1 oval drain during giant farewell
let nextFishId = 1;
const guardianPairs = []; // { aId, bId, t }
let chargeLaneTrail = []; // points while charging a long throw

function wakeColorForFish(f) {
    if (!f) return "rgba(180,210,230,0.22)";
    if (f.isRainbow) {
        const hue = ((f.age || 0) * 140) % 360;
        return "hsla(" + hue + ", 85%, 65%, 0.28)";
    }
    if (f.tamedMonster) return "rgba(190,220,255,0.3)";
    if (f.isMonster) return "rgba(160,30,50,0.28)";
    if (f.isPredator) return "rgba(180,40,50,0.24)";
    if (f.isHero || f.redeemed) return "rgba(80,160,230,0.28)";
    if (f.isPink) return "rgba(255,140,190,0.26)";
    if (f.isPlatinum) return "rgba(220,235,255,0.3)";
    if (f.lineageHue != null) return "hsla(" + f.lineageHue + ", 55%, 60%, 0.22)";
    return "rgba(170,205,220,0.18)";
}

function emitColoredWake(f, speed) {
    if (!f || f.dead || f.golden || gfxQuality <= 0) return;
    if (coloredWakes.length > (gfxQuality >= 2 ? 220 : 110)) coloredWakes.shift();
    const back = f.size * 0.45;
    coloredWakes.push({
        x: f.x - Math.cos(f.dir) * back,
        y: f.y - Math.sin(f.dir) * back,
        vx: -Math.cos(f.dir) * (12 + speed * 0.08),
        vy: -Math.sin(f.dir) * (12 + speed * 0.08),
        life: 0.55 + Math.min(0.55, f.size * 0.004),
        age: 0,
        r: 3 + f.size * 0.04,
        col: wakeColorForFish(f),
    });
}

function updateColoredWakes(dt) {
    for (let i = coloredWakes.length - 1; i >= 0; i--) {
        const w = coloredWakes[i];
        w.age += dt;
        w.x += w.vx * dt;
        w.y += w.vy * dt;
        w.vx *= 0.92;
        w.vy *= 0.92;
        if (w.age >= w.life) coloredWakes.splice(i, 1);
    }
}

function drawColoredWakes(ctx) {
    if (!coloredWakes.length) return;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    for (const w of coloredWakes) {
        const u = 1 - w.age / w.life;
        ctx.globalAlpha = Math.max(0, u * 0.85);
        ctx.fillStyle = w.col;
        ctx.beginPath();
        ctx.ellipse(w.x, w.y, w.r * (1.2 + (1 - u)), w.r * 0.55, 0, 0, Math.PI * 2);
        ctx.fill();
    }
    ctx.restore();
}

function drawGiantCausticSpotlight(ctx) {
    if (!scenery.sun || nightMode || crystalMode || gfxQuality <= 0) return;
    let best = null, bs = 0;
    for (const f of fishes) {
        if (f.dead || f.golden) continue;
        if (f.size > bs) { bs = f.size; best = f; }
    }
    if (whale && !whale.dead && whale.size > bs) { best = whale; bs = whale.size; }
    if (shark && !shark.dead && shark.size > bs) { best = shark; bs = shark.size; }
    if (!best || bs < 48) return;
    const x = best.x;
    const y = best.y;
    const rr = bs * 0.85;
    ctx.save();
    ctx.globalCompositeOperation = "screen";
    const g = ctx.createRadialGradient(x, y, 0, x, y, rr);
    g.addColorStop(0, "rgba(255,220,140,0.14)");
    g.addColorStop(0.45, "rgba(255,160,70,0.055)");
    g.addColorStop(1, "rgba(200,100,40,0)");
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(x, y, rr, rr * 0.62, 0.35, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
}

function drawGiantBedReveal(ctx) {
    if (giantBedReveal <= 0.01 || !giantEnding || !giantEnding.fish) return;
    const f = giantEnding.fish;
    const a = Math.min(1, giantBedReveal);
    const rx = Math.min(viewW, viewH) * (0.22 + 0.28 * a);
    const ry = rx * 0.72;
    ctx.save();
    ctx.globalCompositeOperation = "destination-out";
    const g = ctx.createRadialGradient(f.x, f.y, rx * 0.15, f.x, f.y, rx);
    g.addColorStop(0, "rgba(0,0,0," + (0.55 * a) + ")");
    g.addColorStop(0.7, "rgba(0,0,0," + (0.28 * a) + ")");
    g.addColorStop(1, "rgba(0,0,0,0)");
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(f.x, f.y, rx, ry, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
    ctx.save();
    ctx.strokeStyle = "rgba(80,60,40," + (0.18 * a) + ")";
    ctx.lineWidth = 2 + 4 * a;
    ctx.beginPath();
    ctx.ellipse(f.x, f.y, rx * 0.92, ry * 0.92, 0, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
}

function plantRefractionOffset(x, y) {
    if (typeof water === "undefined" || !water.gradientAt) return { x: 0, y: 0 };
    const g = water.gradientAt(x, y);
    if (!g) return { x: 0, y: 0 };
    // Quiet local bend only: noisy wakes must not shake ornaments each frame.
    return {
        x: Math.max(-3.5, Math.min(3.5, (g.gx || 0) * 8)),
        y: Math.max(-3.5, Math.min(3.5, (g.gy || 0) * 8)),
    };
}

function queuePetEcho(source) {
    if (!source || source.dead) return;
    const base = (source.type && source.type.petFreq) || 320;
    let n = 0;
    for (const f of fishes) {
        if (f === source || f.dead || f.golden || f.isRainbow) continue;
        const d = Math.hypot(f.x - source.x, f.y - source.y);
        if (d > 160) continue;
        petEchoQueue.push({
            delay: 0.12 + n * 0.08 + d * 0.0004,
            x: f.x, y: f.y,
            freq: base * (0.92 + (f.type.register || 1) * 0.08) * weatherPitchMul(),
            pan: Math.max(-1, Math.min(1, (f.x / viewW) * 2 - 1)),
        });
        n++;
        if (n >= 7) break;
    }
}

function updatePetEchoes(dt) {
    for (let i = petEchoQueue.length - 1; i >= 0; i--) {
        const e = petEchoQueue[i];
        e.delay -= dt;
        if (e.delay > 0) continue;
        Audio.fishNote({
            freq: e.freq,
            wave: "sine",
            pan: e.pan,
            dur: 0.28,
            level: 0.035,
            partialAmt: 0.2,
            bright: 0.85,
        });
        water.disturb(e.x, e.y, 3, 18);
        petEchoQueue.splice(i, 1);
    }
}

function playSchoolingHarmony(biter) {
    if (!biter || gfxQuality <= 0) return;
    const base = 220 * (biter.type.register || 1) * weatherPitchMul();
    const ratios = [1, 5 / 4, 3 / 2];
    let i = 0;
    for (const f of fishes) {
        if (f === biter || f.dead) continue;
        if (Math.hypot(f.x - biter.x, f.y - biter.y) > 120) continue;
        const r = ratios[i % ratios.length];
        Audio.fishNote({
            freq: base * r * (f.type.register || 1),
            wave: "triangle",
            pan: Math.max(-1, Math.min(1, (f.x / viewW) * 2 - 1)),
            dur: 0.22,
            level: 0.03,
            partialAmt: 0.15,
            bright: 1.1,
        });
        i++;
        if (i >= 3) break;
    }
}

function addCurrentLanePoint(x, y, dx, dy) {
    const len = Math.hypot(dx, dy) || 1;
    currentLanes.push({
        x: x, y: y,
        ux: dx / len,
        uy: dy / len,
        life: CONFIG.currentLaneLife,
        age: 0,
        strength: 55 + Math.min(70, len * 0.4),
    });
    if (currentLanes.length > 80) currentLanes.shift();
}

function updateCurrentLanes(dt) {
    for (let i = currentLanes.length - 1; i >= 0; i--) {
        const c = currentLanes[i];
        c.age += dt;
        if (c.age >= c.life) currentLanes.splice(i, 1);
    }
}

function currentFlowAt(x, y) {
    let fx = 0, fy = 0;
    const range = strongerCurrentsOwned ? STRONGER_CURRENTS_RANGE : 70;
    const forceMul = strongerCurrentsOwned ? STRONGER_CURRENTS_MULT : 1;
    for (const c of currentLanes) {
        const d = Math.hypot(c.x - x, c.y - y);
        if (d > range) continue;
        const u = 1 - c.age / c.life;
        const w = (1 - d / range) * u;
        fx += c.ux * c.strength * w * forceMul;
        fy += c.uy * c.strength * w * forceMul;
    }
    return { x: fx, y: fy };
}

function applyCurrentToEntity(ent, dt, mult) {
    if (!ent || !currentLanes.length) return;
    const f = currentFlowAt(ent.x, ent.y);
    if (!f.x && !f.y) return;
    const m = mult != null ? mult : 1;
    ent.x += f.x * m * dt;
    ent.y += f.y * m * dt;
}

function drawCurrentLanes(ctx) {
    if (!currentLanes.length) return;
    ctx.save();
    ctx.lineCap = "round";
    for (const c of currentLanes) {
        const u = 1 - c.age / c.life;
        // Soft ink ribbon: glow wash then a thin bright core.
        ctx.strokeStyle = "rgba(120,180,210," + (0.1 * u) + ")";
        ctx.lineWidth = 7 + 6 * u;
        ctx.beginPath();
        ctx.moveTo(c.x - c.ux * 14, c.y - c.uy * 14);
        ctx.lineTo(c.x + c.ux * 22, c.y + c.uy * 22);
        ctx.stroke();
        ctx.strokeStyle = "rgba(200,235,250," + (0.22 * u) + ")";
        ctx.lineWidth = 1.6 + 2.4 * u;
        ctx.beginPath();
        ctx.moveTo(c.x - c.ux * 12, c.y - c.uy * 12);
        ctx.lineTo(c.x + c.ux * 20, c.y + c.uy * 20);
        ctx.stroke();
    }
    ctx.restore();
}

function beginWeatherMood(forceKind) {
    const kinds = ["mist", "pollen", "fireflies"];
    const kind = forceKind || kinds[Math.floor(Math.random() * kinds.length)];
    if (kind === "mist" && Math.random() < 0.45 && typeof maybeSpawnIcePatch === "function") {
        maybeSpawnIcePatch();
        maybeSpawnIcePatch();
    }
    weatherMood = {
        kind: kind,
        t: 0,
        life: 14 + Math.random() * 10,
        pitchMul: kind === "mist" ? 0.92 : kind === "fireflies" ? 1.08 : 1,
        aggressionMul: kind === "mist" ? 0.85 : kind === "pollen" ? 1.05 : 0.95,
        lightTint: kind === "mist" ? [160, 190, 210]
            : kind === "pollen" ? [240, 200, 120]
            : [150, 210, 160],
    };
    weatherParticles.length = 0;
    const n = gfxQuality >= 2 ? 48 : 28;
    for (let i = 0; i < n; i++) {
        let px = Math.random() * viewW;
        let py = Math.random() * viewH;
        // Fireflies cluster near plants and shore rather than open midwater.
        if (kind === "fireflies") {
            const anchors = [];
            for (const p of pondPlants) anchors.push(p);
            if (scenery.lilies) {
                for (const L of sceneryItems.lilies) anchors.push(L);
            }
            if (anchors.length) {
                const a = anchors[Math.floor(Math.random() * anchors.length)];
                px = a.x + (Math.random() - 0.5) * 70;
                py = a.y + (Math.random() - 0.5) * 50;
            } else {
                px = Math.random() < 0.5 ? viewW * (0.05 + Math.random() * 0.18)
                    : viewW * (0.77 + Math.random() * 0.18);
                py = viewH * (0.35 + Math.random() * 0.5);
            }
        }
        weatherParticles.push({
            x: px,
            y: py,
            vx: (Math.random() - 0.5) * (kind === "mist" ? 8 : 18),
            vy: (Math.random() - 0.5) * (kind === "fireflies" ? 12 : 6),
            phase: Math.random() * Math.PI * 2,
            r: kind === "mist" ? 18 + Math.random() * 30 : 1.5 + Math.random() * 2.5,
        });
    }
}

function updateWeather(dt) {
    weatherTimer -= dt;
    if (weatherTimer <= 0) {
        weatherTimer = CONFIG.weatherInterval * (0.7 + Math.random() * 0.6);
        if (!weatherMood && Math.random() < CONFIG.weatherChance) beginWeatherMood();
    }
    if (!weatherMood) return;
    weatherMood.t += dt;
    if (weatherMood.t >= weatherMood.life) {
        weatherMood = null;
        weatherParticles.length = 0;
        return;
    }
    for (const p of weatherParticles) {
        p.phase += dt * 2;
        p.x += p.vx * dt + Math.sin(p.phase) * 4 * dt;
        p.y += p.vy * dt + Math.cos(p.phase * 0.8) * 3 * dt;
        if (p.x < -40) p.x = viewW + 40;
        if (p.x > viewW + 40) p.x = -40;
        if (p.y < -40) p.y = viewH + 40;
        if (p.y > viewH + 40) p.y = -40;
    }
}

function weatherPitchMul() {
    return weatherMood ? weatherMood.pitchMul : 1;
}

function weatherAggressionMul() {
    return weatherMood ? weatherMood.aggressionMul : 1;
}

function drawWeather(ctx) {
    if (!weatherMood) return;
    const fade = Math.min(1, weatherMood.t * 0.5, (weatherMood.life - weatherMood.t) * 0.4);
    ctx.save();
    // Whole-pond lighting wash: mist cools, pollen warms, fireflies stay subtle.
    if (weatherMood.lightTint && fade > 0.02) {
        const lt = weatherMood.lightTint;
        const washA = weatherMood.kind === "fireflies" ? 0.035 : 0.07;
        ctx.fillStyle = "rgba(" + lt[0] + "," + lt[1] + "," + lt[2] + "," + (washA * fade) + ")";
        ctx.fillRect(0, 0, viewW, viewH);
    }
    if (weatherMood.kind === "mist") {
        ctx.fillStyle = "rgba(200,220,230," + (0.08 * fade) + ")";
        ctx.fillRect(0, 0, viewW, viewH);
        for (const p of weatherParticles) {
            const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.r);
            g.addColorStop(0, "rgba(220,235,245," + (0.07 * fade) + ")");
            g.addColorStop(1, "rgba(220,235,245,0)");
            ctx.fillStyle = g;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
            ctx.fill();
        }
    } else if (weatherMood.kind === "pollen") {
        for (const p of weatherParticles) {
            ctx.fillStyle = "rgba(240,210,120," + ((0.25 + 0.2 * Math.sin(p.phase)) * fade) + ")";
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
            ctx.fill();
        }
    } else {
        for (const p of weatherParticles) {
            const tw = 0.35 + 0.65 * Math.abs(Math.sin(p.phase * 1.7));
            ctx.fillStyle = "rgba(180,255,160," + (tw * 0.55 * fade) + ")";
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.r * (0.8 + tw * 0.5), 0, Math.PI * 2);
            ctx.fill();
        }
    }
    ctx.restore();
}

function noteHardPondSplash(v, x, y) {
    if (v < 0.55) return;
    pendingGlassRain = Math.min(2.8, pendingGlassRain + 0.35 + v * 0.5);
    glassRainBurst = {
        t: 0,
        life: 0.9 + v * 0.5,
        drops: Array.from({ length: 10 + Math.floor(v * 12) }, function () {
            return {
                x: x + (Math.random() - 0.5) * 120,
                y: y + (Math.random() - 0.5) * 80,
                r: 4 + Math.random() * 10,
                age: Math.random() * 0.2,
            };
        }),
    };
}

function updateGlassCrossover(dt) {
    if (pendingGlassRain > 0) pendingGlassRain = Math.max(0, pendingGlassRain - dt * 0.15);
    if (glassRainBurst) {
        glassRainBurst.t += dt;
        if (glassRainBurst.t >= glassRainBurst.life) glassRainBurst = null;
    }
}

function flushPendingGlassRain() {
    if (pendingGlassRain <= 0 || typeof spawnWindowRipple !== "function") return;
    const n = Math.min(14, 4 + Math.floor(pendingGlassRain * 5));
    for (let i = 0; i < n; i++) {
        spawnWindowRipple(
            Math.random() * viewW,
            Math.random() * viewH,
            0.25 + Math.random() * 0.45
        );
    }
    pendingGlassRain = 0;
}

function drawGlassRainOverlay(ctx) {
    if (!glassRainBurst) return;
    const u = 1 - glassRainBurst.t / glassRainBurst.life;
    ctx.save();
    ctx.globalAlpha = Math.max(0, u * 0.55);
    for (const d of glassRainBurst.drops) {
        const age = glassRainBurst.t + d.age;
        const rr = d.r * (0.7 + age * 0.8);
        ctx.strokeStyle = "rgba(200,230,255,0.55)";
        ctx.lineWidth = 1.2;
        ctx.beginPath();
        ctx.arc(d.x, d.y + age * 18, rr, 0, Math.PI * 2);
        ctx.stroke();
    }
    ctx.restore();
}

function assignFishId(f) {
    if (!f._fid) f._fid = nextFishId++;
    return f._fid;
}

function findFishById(id) {
    for (const f of fishes) if (f._fid === id) return f;
    return null;
}

function maybeSpawnMirrorTwin(host) {
    if (!host || host.dead || host.isMirror || host.isRainbow) return null;
    if (Math.random() > CONFIG.mirrorFishChance) return null;
    const twin = new Fish(host.type);
    twin.isMirror = true;
    twin.mirrorOf = assignFishId(host);
    twin.mirrorTrail = [];
    twin.isHero = false;
    twin.isPredator = false;
    twin.size = host.size * 0.92;
    twin.baseSpeed = host.baseSpeed;
    twin.x = host.x + Math.cos(host.dir + Math.PI) * 28;
    twin.y = host.y + Math.sin(host.dir + Math.PI) * 28;
    twin.dir = host.dir;
    fishes.push(twin);
    return twin;
}

function updateMirrorFish(f, dt) {
    if (!f.isMirror) return false;
    const host = findFishById(f.mirrorOf);
    if (!host || host.dead) {
        f.dead = true;
        return true;
    }
    host.mirrorTrail = host.mirrorTrail || [];
    host.mirrorTrail.push({ x: host.x, y: host.y, dir: host.dir, t: performance.now() });
    while (host.mirrorTrail.length > 45) host.mirrorTrail.shift();
    const sample = host.mirrorTrail[0];
    if (sample) {
        const k = 1 - Math.exp(-5 * dt);
        f.x += (sample.x - f.x) * k;
        f.y += (sample.y - f.y) * k;
        f.dir += normAngle(sample.dir - f.dir) * k;
    }
    f.size += (host.size * 0.92 - f.size) * Math.min(1, 2 * dt);
    if (f.target && host.target && f.target === host.target && !f.target.eaten) {
        const d = Math.hypot(f.x - host.x, f.y - host.y);
        if (d < (f.size + host.size) * 0.35) {
            host.isMirror = false;
            f.dead = true;
            if (Math.random() < 0.55) host.turnToRainbow();
            else if (Math.random() < 0.35) host.turnToPlatinum();
            else host.grow(10, { huge: true });
            spawnSplash((f.x + host.x) * 0.5, (f.y + host.y) * 0.5, 12, 0.5);
            return true;
        }
    }
    return true;
}

function updateGuardianPairs(dt) {
    for (let i = guardianPairs.length - 1; i >= 0; i--) {
        const p = guardianPairs[i];
        const a = findFishById(p.aId);
        const b = findFishById(p.bId);
        if (!a || !b || a.dead || b.dead) {
            guardianPairs.splice(i, 1);
            continue;
        }
        p.t += dt;
        const d = Math.hypot(a.x - b.x, a.y - b.y);
        if (d > 220) {
            guardianPairs.splice(i, 1);
            continue;
        }
        if (d > 90) {
            const k = 18 * dt;
            a.x += (b.x - a.x) / d * k;
            a.y += (b.y - a.y) / d * k;
            b.x += (a.x - b.x) / d * k;
            b.y += (a.y - b.y) / d * k;
        }
    }
    for (const a of fishes) {
        if (a.dead || !a.tamedMonster) continue;
        assignFishId(a);
        for (const b of fishes) {
            if (b === a || b.dead || !(b.isHero || b.redeemed) || b.tamedMonster) continue;
            if (Math.hypot(a.x - b.x, a.y - b.y) > 110) continue;
            assignFishId(b);
            const exists = guardianPairs.some(function (p) {
                return (p.aId === a._fid && p.bId === b._fid)
                    || (p.aId === b._fid && p.bId === a._fid);
            });
            if (!exists && guardianPairs.length < 4) {
                guardianPairs.push({ aId: a._fid, bId: b._fid, t: 0 });
            }
        }
    }
}

function drawGuardianPairs(ctx) {
    ctx.save();
    for (const p of guardianPairs) {
        const a = findFishById(p.aId);
        const b = findFishById(p.bId);
        if (!a || !b) continue;
        const pulse = 0.35 + 0.25 * Math.sin(p.t * 3);
        ctx.strokeStyle = "rgba(160,210,255," + pulse + ")";
        ctx.lineWidth = 1.4;
        ctx.setLineDash([5, 6]);
        ctx.beginPath();
        ctx.moveTo(a.x, a.y);
        ctx.lineTo(b.x, b.y);
        ctx.stroke();
        ctx.setLineDash([]);
    }
    ctx.restore();
}

function heroTerritoryRadius(f) {
    if (!f || !(f.isHero || f.redeemed) || f.isMonster || f.isPredator) return 0;
    if (f.size < CONFIG.territoryHeroSize) return 0;
    return f.size * 1.35 + 40;
}

function territoryFearAt(x, y) {
    let fear = 0;
    for (const f of fishes) {
        const r = heroTerritoryRadius(f);
        if (r <= 0) continue;
        const d = Math.hypot(f.x - x, f.y - y);
        if (d < r) fear = Math.max(fear, 1 - d / r);
    }
    return fear;
}

function drawTerritoryRings(ctx) {
    ctx.save();
    for (const f of fishes) {
        const r = heroTerritoryRadius(f);
        if (r <= 0) continue;
        const pulse = 0.5 + 0.5 * Math.sin((f.age || 0) * 1.5);
        ctx.strokeStyle = "rgba(70,150,220," + (0.08 + pulse * 0.06) + ")";
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(f.x, f.y, r, 0, Math.PI * 2);
        ctx.stroke();
        ctx.fillStyle = "rgba(70,150,220," + (0.02 + pulse * 0.015) + ")";
        ctx.fill();
    }
    ctx.restore();
}

function mixLineageHue(a, b) {
    const ha = a.lineageHue != null ? a.lineageHue : (a.isPink ? 330 : null);
    const hb = b.lineageHue != null ? b.lineageHue : (b.isPink ? 330 : null);
    if (ha == null && hb == null) return 300 + Math.random() * 40;
    if (ha == null) return hb;
    if (hb == null) return ha;
    return (ha + hb) * 0.5 + (Math.random() - 0.5) * 18;
}

function tryBeginRainbowDuet(fish) {
    const partner = fishes.find(function (f) {
        return f !== fish && f.isRainbow && f.rainbowLeaving
            && (f.rainbowPhase === "logo" || f.rainbowPhase === "erratic") && f.eggPath;
    });
    if (!partner || !partner.eggPath) return false;
    // Mirror the partner path once both are writing; during erratic just link ids.
    if (partner.rainbowPhase === "logo") {
        const path = partner.eggPath.map(function (p, i) {
            const cx = viewW * 0.5;
            return {
                x: cx * 2 - p.x + Math.sin(i * 0.2) * 4,
                y: p.y + Math.cos(i * 0.15) * 3,
            };
        });
        fish.eggPath = path;
        fish.eggIndex = Math.min(fish.eggIndex, Math.floor(path.length * 0.15));
    }
    fish._duetPartner = partner._fid || assignFishId(partner);
    partner._duetPartner = assignFishId(fish);
    return true;
}

function spendStashVariants(costs) {
    const need = Object.assign({}, costs);
    for (const k of Object.keys(need)) {
        if (countStashVariant(k) < need[k]) return false;
    }
    for (const k of Object.keys(need)) {
        let left = need[k];
        for (let i = foodStash.length - 1; i >= 0 && left > 0; i--) {
            if (foodStash[i] !== k) continue;
            foodStash.splice(i, 1);
            if (k === "normal") normalFoodBank = Math.max(0, normalFoodBank - 1);
            left--;
        }
    }
    clearArmedStashIfGone();
    saveFoodStash();
    renderFoodStashUI();
    updateMarketUI();
    return true;
}

function marketCraftMirrorFood() {
    if (!marketUnlocked) return;
    if (!spendStashVariants(RECIPE_MIRROR_COST)) return;
    stashFood("grower");
    if (Audio.rainbowChime) Audio.rainbowChime(0);
    const host = fishes.find(function (f) { return !f.dead && !f.isMirror && !f.golden; });
    if (host) {
        const twin = new Fish(host.type);
        twin.isMirror = true;
        twin.mirrorOf = assignFishId(host);
        twin.isHero = false;
        twin.isPredator = false;
        twin.size = host.size * 0.92;
        twin.baseSpeed = host.baseSpeed;
        twin.x = host.x - 30;
        twin.y = host.y;
        twin.dir = host.dir;
        fishes.push(twin);
        spawnSplash(twin.x, twin.y, 8, 0.35);
    }
    updateMarketUI();
    markFirstInteraction();
}

function marketCraftStormFood() {
    if (!marketUnlocked) return;
    if (!spendStashVariants(RECIPE_STORM_COST)) return;
    stashFood("rainbow");
    beginWeatherMood("mist");
    pendingGlassRain = Math.min(2.8, pendingGlassRain + 1.2);
    if (Audio.rainbowChime) Audio.rainbowChime(0);
    updateMarketUI();
    markFirstInteraction();
}


// ===========================================================================
// FLAVOR PACK 2: night glow, bubbles, silt, whirlpools, memory, comet, dusk
// ===========================================================================
const breathBubbles = [];
const siltClouds = [];
const sonicRings = [];
const petMemories = [];
const whirlpools = [];
let cometVisitor = null;
let starWishSparks = [];
let duskBlend = 0; // unused remnant; day light is golden hour when sun is on
let icePatches = [];

function emitBreathBubbles(x, y, n, col) {
    if (gfxQuality <= 0) return;
    const count = Math.min(n || 3, gfxQuality >= 2 ? 8 : 5);
    for (let i = 0; i < count; i++) {
        if (breathBubbles.length > 90) breathBubbles.shift();
        breathBubbles.push({
            x: x + (Math.random() - 0.5) * 10,
            y: y + (Math.random() - 0.5) * 6,
            r: 1.2 + Math.random() * 2.4,
            vy: -(18 + Math.random() * 28),
            vx: (Math.random() - 0.5) * 10,
            age: 0,
            life: 0.7 + Math.random() * 0.6,
            col: col || "rgba(210,235,255,0.55)",
        });
    }
}

function updateBreathBubbles(dt) {
    for (let i = breathBubbles.length - 1; i >= 0; i--) {
        const b = breathBubbles[i];
        b.age += dt;
        b.x += b.vx * dt;
        b.y += b.vy * dt;
        b.vy *= 0.98;
        if (b.age >= b.life) breathBubbles.splice(i, 1);
    }
}

function drawBreathBubbles(ctx) {
    if (!breathBubbles.length) return;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    for (const b of breathBubbles) {
        const u = 1 - b.age / b.life;
        ctx.globalAlpha = Math.max(0, u * 0.7);
        ctx.strokeStyle = b.col;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.arc(b.x, b.y, b.r * (0.8 + u * 0.4), 0, Math.PI * 2);
        ctx.stroke();
    }
    ctx.restore();
}

function emitSiltCloud(x, y, size) {
    if (gfxQuality <= 0 || !scenery.bed) return;
    if (siltClouds.length > 40) siltClouds.shift();
    siltClouds.push({
        x: x, y: y,
        r: Math.min(90, 18 + size * 0.35),
        age: 0,
        life: 1.4 + Math.min(1.2, size * 0.01),
    });
}

function updateSiltClouds(dt) {
    for (let i = siltClouds.length - 1; i >= 0; i--) {
        siltClouds[i].age += dt;
        if (siltClouds[i].age >= siltClouds[i].life) siltClouds.splice(i, 1);
    }
}

function drawSiltClouds(ctx) {
    if (!siltClouds.length) return;
    ctx.save();
    for (const s of siltClouds) {
        const u = 1 - s.age / s.life;
        const g = ctx.createRadialGradient(s.x, s.y, 0, s.x, s.y, s.r * (1.1 - u * 0.2));
        g.addColorStop(0, "rgba(90,70,45," + (0.16 * u) + ")");
        g.addColorStop(0.55, "rgba(70,55,35," + (0.08 * u) + ")");
        g.addColorStop(1, "rgba(50,40,25,0)");
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(s.x, s.y, s.r * (1.1 - u * 0.2), 0, Math.PI * 2);
        ctx.fill();
    }
    ctx.restore();
}

function emitSonicRing(x, y, freq) {
    if (gfxQuality <= 0) return;
    if (sonicRings.length > 24) sonicRings.shift();
    const pitch = Math.max(0, Math.min(1, (freq - 150) / 900));
    sonicRings.push({
        x: x, y: y,
        age: 0,
        life: 0.85,
        hue: 180 + pitch * 140,
        maxR: 28 + pitch * 55,
    });
}

function updateSonicRings(dt) {
    for (let i = sonicRings.length - 1; i >= 0; i--) {
        sonicRings[i].age += dt;
        if (sonicRings[i].age >= sonicRings[i].life) sonicRings.splice(i, 1);
    }
}

function drawSonicRings(ctx) {
    if (!sonicRings.length) return;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    for (const r of sonicRings) {
        const u = r.age / r.life;
        const rad = r.maxR * (0.15 + u * 0.85);
        ctx.strokeStyle = "hsla(" + r.hue + ",70%,70%," + ((1 - u) * 0.35) + ")";
        ctx.lineWidth = 1.4 + (1 - u) * 1.6;
        ctx.beginPath();
        ctx.arc(r.x, r.y, rad, 0, Math.PI * 2);
        ctx.stroke();
    }
    ctx.restore();
}

function rememberPetSpot(x, y) {
    petMemories.push({ x: x, y: y, age: 0, life: 34 + Math.random() * 14 });
    if (petMemories.length > 16) petMemories.shift();
}

function updatePetMemories(dt) {
    for (let i = petMemories.length - 1; i >= 0; i--) {
        petMemories[i].age += dt;
        if (petMemories[i].age >= petMemories[i].life) petMemories.splice(i, 1);
    }
}

function drawPetMemories(ctx) {
    if (!petMemories.length) return;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    for (const m of petMemories) {
        const u = 1 - m.age / m.life;
        const pulse = 0.5 + 0.5 * Math.sin(m.age * 3);
        const g = ctx.createRadialGradient(m.x, m.y, 0, m.x, m.y, 26);
        g.addColorStop(0, "rgba(255,210,160," + (0.12 * u * pulse) + ")");
        g.addColorStop(1, "rgba(255,180,120,0)");
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.arc(m.x, m.y, 26, 0, Math.PI * 2);
        ctx.fill();
    }
    ctx.restore();
}

function nearestPetMemory(x, y, range) {
    let best = null, bd = range || 160;
    for (const m of petMemories) {
        const d = Math.hypot(m.x - x, m.y - y);
        if (d < bd) { bd = d; best = m; }
    }
    return best;
}

function spawnWhirlpool(x, y, power, life) {
    if (whirlpools.length > 6) whirlpools.shift();
    whirlpools.push({
        x: x, y: y,
        power: power || 40,
        age: 0,
        life: life || 5,
        spin: Math.random() < 0.5 ? 1 : -1,
    });
}

function updateWhirlpools(dt) {
    for (let i = whirlpools.length - 1; i >= 0; i--) {
        const w = whirlpools[i];
        w.age += dt;
        if (w.age >= w.life) {
            whirlpools.splice(i, 1);
            continue;
        }
        const u = 1 - w.age / w.life;
        const reach = 50 + w.power * 0.6;
        const pull = w.power * u * dt;
        for (const f of foods) {
            if (f.eaten) continue;
            const dx = w.x - f.x, dy = w.y - f.y;
            const d = Math.hypot(dx, dy) || 1;
            if (d > reach) continue;
            f.x += dx / d * pull * 0.55;
            f.y += dy / d * pull * 0.55;
            // Spiral aside.
            f.x += -dy / d * pull * 0.35 * w.spin;
            f.y += dx / d * pull * 0.35 * w.spin;
        }
        for (const o of obstacles) {
            const dx = w.x - o.x, dy = w.y - o.y;
            const d = Math.hypot(dx, dy) || 1;
            if (d > reach * 1.1) continue;
            o.vx = (o.vx || 0) + dx / d * pull * 0.8;
            o.vy = (o.vy || 0) + dy / d * pull * 0.8;
            o.spin = (o.spin || 0) + w.spin * 0.4 * dt;
        }
        if (Math.random() < 0.12) water.disturb(w.x, w.y, 8, 30 * u);
    }
}

function drawWhirlpools(ctx) {
    if (!whirlpools.length) return;
    ctx.save();
    for (const w of whirlpools) {
        const u = 1 - w.age / w.life;
        const reach = 50 + w.power * 0.6;
        ctx.strokeStyle = "rgba(140,190,220," + (0.14 * u) + ")";
        ctx.lineWidth = 1.5;
        for (let k = 0; k < 3; k++) {
            const a0 = w.age * 2.2 * w.spin + k * 2.1;
            ctx.beginPath();
            for (let i = 0; i <= 18; i++) {
                const t = i / 18;
                const ang = a0 + t * Math.PI * 2;
                const rad = reach * (0.2 + t * 0.75);
                const x = w.x + Math.cos(ang) * rad;
                const y = w.y + Math.sin(ang) * rad * 0.72;
                if (i === 0) ctx.moveTo(x, y);
                else ctx.lineTo(x, y);
            }
            ctx.stroke();
        }
    }
    ctx.restore();
}

function drawMoonBedCaustics(ctx) {
    if (!nightMode || gfxQuality <= 0) return;
    ctx.save();
    ctx.globalCompositeOperation = "screen";
    const t = sunPhase;
    const n = gfxQuality >= 2 ? 14 : 7;
    for (let i = 0; i < n; i++) {
        const x = ((i * 151.3 + Math.sin(t * 0.3 + i) * 60) % viewW + viewW) % viewW;
        const y = ((i * 97.7 + Math.cos(t * 0.26 + i * 1.2) * 50) % viewH + viewH) % viewH;
        const tw = 0.4 + 0.6 * Math.abs(Math.sin(t * 0.8 + i));
        const rr = 20 + tw * 26;
        const g = ctx.createRadialGradient(x, y, 0, x, y, rr);
        g.addColorStop(0, "rgba(160,200,255," + (0.045 * tw) + ")");
        g.addColorStop(0.5, "rgba(100,150,220," + (0.02 * tw) + ")");
        g.addColorStop(1, "rgba(60,100,180,0)");
        ctx.fillStyle = g;
        ctx.beginPath();
        ctx.ellipse(x, y, rr, rr * 0.6, i, 0, Math.PI * 2);
        ctx.fill();
    }
    ctx.restore();
}

function drawDuskWash(ctx) {
    // No shifting day lighting. Golden hour is handled only by drawSunAmbience.
    duskBlend = 0;
}

function emitBiolumWake(f) {
    if (!nightMode || !f || f.dead || f.golden || gfxQuality <= 0) return;
    if (coloredWakes.length > 200) coloredWakes.shift();
    const hue = f.isHero ? 200 : f.isPredator ? 350 : f.isRainbow ? ((f.age || 0) * 140) % 360 : 160;
    coloredWakes.push({
        x: f.x - Math.cos(f.dir) * f.size * 0.4,
        y: f.y - Math.sin(f.dir) * f.size * 0.4,
        vx: -Math.cos(f.dir) * 8,
        vy: -Math.sin(f.dir) * 8,
        life: 0.9,
        age: 0,
        r: 4 + f.size * 0.05,
        col: "hsla(" + hue + ", 85%, 70%, 0.4)",
    });
}

function updateSchoolOrbit(dt) {
    // Tiny peaceful fish ease into soft orbits around large heroes.
    for (const hero of fishes) {
        if (hero.dead || !(hero.isHero || hero.redeemed) || hero.size < 55) continue;
        for (const f of fishes) {
            if (f === hero || f.dead || f.isPredator || f.isMonster || f.isRainbow || f.isHero) continue;
            if (f.size > hero.size * 0.45) continue;
            const d = Math.hypot(f.x - hero.x, f.y - hero.y);
            if (d < 40 || d > hero.size * 1.6) continue;
            const ang = Math.atan2(f.y - hero.y, f.x - hero.x) + 0.55 * dt;
            const wantR = Math.min(d, hero.size * 0.95);
            const tx = hero.x + Math.cos(ang) * wantR;
            const ty = hero.y + Math.sin(ang) * wantR;
            const k = 1 - Math.exp(-1.2 * dt);
            f.x += (tx - f.x) * k * 0.35;
            f.y += (ty - f.y) * k * 0.35;
        }
    }
}

function updateMemorySeek(dt) {
    // Calm fish prefer remembered pet spots and linger near them more often.
    for (const f of fishes) {
        if (f.dead || f.isPredator || f.isMonster || f.isRainbow) continue;
        // Recently petted fish keep easing toward the touch spot.
        const lingering = (f.petTimer || 0) > 0.15;
        if (!lingering && Math.random() > 0.09) continue;
        const m = nearestPetMemory(f.x, f.y, lingering ? 300 : 260);
        if (!m) continue;
        const want = Math.atan2(m.y - f.y, m.x - f.x);
        const steer = lingering ? 3.4 : 2.8;
        f.dir += normAngle(want - f.dir) * Math.min(1, steer * dt);
        const step = Math.min((lingering ? 36 : 32) * dt, Math.hypot(m.x - f.x, m.y - f.y) * (lingering ? 0.42 : 0.38));
        f.x += Math.cos(want) * step;
        f.y += Math.sin(want) * step;
    }
}

function spawnShootingStar(x, y, tx, ty, opts) {
    const dir = Math.atan2(ty - y, tx - x);
    const dist = Math.max(80, Math.hypot(tx - x, ty - y));
    // Fast streak: cross the pond in about a second so catching it takes quick aim.
    const speed = (opts && opts.speed) || (560 + Math.random() * 220);
    const life = dist / speed + 0.12;
    cometVisitor = {
        x: x, y: y, tx: tx, ty: ty,
        vx: Math.cos(dir) * speed,
        vy: Math.sin(dir) * speed,
        dir: dir,
        t: 0,
        life: life,
        // Must tap while the streak is still bright.
        catchUntil: Math.min(1.05, life * 0.58),
        hitR: 58,
        caught: false,
        lateMiss: false,
        burst: 0,
    };
    if (Audio.starfall) {
        Audio.starfall(Math.max(-1, Math.min(1, (x / viewW) * 2 - 1)));
    }
    return cometVisitor;
}

function maybeSpawnComet(dt) {
    if (cometVisitor) {
        const c = cometVisitor;
        c.t += dt;
        if (c.caught) {
            c.burst = Math.min(1, (c.burst || 0) + dt * 3.2);
            c.x += c.vx * dt * 0.35;
            c.y += c.vy * dt * 0.35;
            c.vx *= Math.exp(-2.4 * dt);
            c.vy *= Math.exp(-2.4 * dt);
            if (c.t > c.life) cometVisitor = null;
            return;
        }
        c.x += c.vx * dt;
        c.y += c.vy * dt;
        if (Math.random() < 0.42) {
            water.disturb(c.x, c.y, 5, 34);
            emitColoredWake({
                x: c.x, y: c.y, dir: c.dir,
                size: 22, age: c.t, isRainbow: true, dead: false, golden: false,
            }, 110);
        }
        const pad = 70;
        const gone = c.t > c.life
            || c.x < -pad || c.x > viewW + pad
            || c.y < -pad || c.y > viewH + pad;
        if (gone) cometVisitor = null;
        return;
    }
    // Shooting stars only under the moon pond sky.
    if (!nightMode || pondFinaleActive() || Math.random() > 0.00055) return;
    const side = Math.floor(Math.random() * 4);
    let x, y, tx, ty;
    if (side === 0) { x = -40; y = Math.random() * viewH; tx = viewW + 40; ty = Math.random() * viewH; }
    else if (side === 1) { x = viewW + 40; y = Math.random() * viewH; tx = -40; ty = Math.random() * viewH; }
    else if (side === 2) { x = Math.random() * viewW; y = -40; tx = Math.random() * viewW; ty = viewH + 40; }
    else { x = Math.random() * viewW; y = viewH + 40; tx = Math.random() * viewW; ty = -40; }
    spawnShootingStar(x, y, tx, ty);
}

function emitStarWishSparks(x, y, n, late) {
    if (gfxQuality <= 0) return;
    const count = Math.min(n || 18, gfxQuality >= 2 ? 28 : 16);
    for (let i = 0; i < count; i++) {
        if (starWishSparks.length > 80) starWishSparks.shift();
        const a = Math.random() * Math.PI * 2;
        const sp = late ? (40 + Math.random() * 70) : (90 + Math.random() * 180);
        starWishSparks.push({
            x: x, y: y,
            vx: Math.cos(a) * sp,
            vy: Math.sin(a) * sp,
            age: 0,
            life: late ? (0.35 + Math.random() * 0.25) : (0.55 + Math.random() * 0.55),
            r: late ? (1 + Math.random()) : (1.4 + Math.random() * 2.2),
            hue: late ? (210 + Math.random() * 40) : (40 + Math.random() * 280),
        });
    }
}

function updateStarWishSparks(dt) {
    for (let i = starWishSparks.length - 1; i >= 0; i--) {
        const s = starWishSparks[i];
        s.age += dt;
        s.x += s.vx * dt;
        s.y += s.vy * dt;
        s.vx *= Math.exp(-1.8 * dt);
        s.vy *= Math.exp(-1.8 * dt);
        if (s.age >= s.life) starWishSparks.splice(i, 1);
    }
}

function drawStarWishSparks(ctx) {
    if (!starWishSparks.length) return;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    for (const s of starWishSparks) {
        const u = 1 - s.age / s.life;
        ctx.globalAlpha = Math.max(0, u * 0.95);
        ctx.fillStyle = `hsla(${s.hue}, 90%, 78%, 1)`;
        ctx.beginPath();
        ctx.arc(s.x, s.y, s.r * (0.7 + u * 0.6), 0, Math.PI * 2);
        ctx.fill();
    }
    ctx.restore();
}

function shootingStarHitTest(x, y) {
    if (!cometVisitor || cometVisitor.caught || cometVisitor.lateMiss) return false;
    const c = cometVisitor;
    const hitR = c.hitR || 58;
    if (Math.hypot(x - c.x, y - c.y) <= hitR) return true;
    // Allow a bit of trail so a near-miss on the streak still counts.
    for (let i = 1; i <= 5; i++) {
        const bx = c.x - Math.cos(c.dir) * i * 12;
        const by = c.y - Math.sin(c.dir) * i * 12;
        if (Math.hypot(x - bx, y - by) <= hitR * (0.92 - i * 0.06)) return true;
    }
    return false;
}

function grantShootingStarWish(x, y) {
    const c = cometVisitor;
    if (!c) return;
    c.caught = true;
    c.burst = 0.01;
    c.wishTrail = 1;
    c.life = Math.min(c.life, c.t + 0.55);
    c.vx *= 0.25;
    c.vy *= 0.25;
    // Warm spark trail along the streak so the catch reads clearly.
    emitStarWishSparks(x, y, 30, false);
    for (let i = 1; i <= 10; i++) {
        const bx = x - Math.cos(c.dir) * i * 16;
        const by = y - Math.sin(c.dir) * i * 16;
        emitStarWishSparks(bx, by, 4, false);
    }
    water.disturb(x, y, 28, 140);
    spawnSplash(x, y, 16, 0.55);
    if (Audio.rainbowChime) Audio.rainbowChime(Math.max(-1, Math.min(1, (x / viewW) * 2 - 1)));
    if (Audio.starfall) Audio.starfall(Math.max(-1, Math.min(1, (x / viewW) * 2 - 1)));

    // Wish gifts: rare food at the catch, plus one saved rainbow pellet.
    const dropN = 2 + (Math.random() < 0.35 ? 1 : 0);
    for (let i = 0; i < dropN; i++) {
        const fx = Math.max(24, Math.min(viewW - 24, x + (Math.random() - 0.5) * 36));
        const fy = Math.max(24, Math.min(viewH - 24, y + (Math.random() - 0.5) * 36));
        let flags = { rainbow: true };
        if (i === 1 && platinumUnlocked && Math.random() < 0.5) flags = { platinum: true };
        else if (i === 1 && Math.random() < 0.4) flags = { golden: true };
        while (foods.length >= CONFIG.maxFoods) {
            const common = foods.findIndex((f) => !isRareFoodFlags(f));
            if (common >= 0) foods.splice(common, 1);
            else foods.shift();
        }
        foods.push(new Food(fx, fy, 9 + Math.random() * 4, flags));
    }
    if (typeof stashFood === "function") stashFood("rainbow");
    if (typeof beginWeatherMood === "function") beginWeatherMood("fireflies");
    if (typeof emitBiolumWake === "function") {
        for (const f of fishes) {
            if (f.dead || Math.hypot(f.x - x, f.y - y) > 200) continue;
            emitBiolumWake(f);
            f.petTimer = Math.max(f.petTimer || 0, 0.9);
        }
    }
    markFirstInteraction();
}

function missShootingStarLate(x, y) {
    const c = cometVisitor;
    if (!c) return;
    c.lateMiss = true;
    c.life = Math.min(c.life, c.t + 0.28);
    emitStarWishSparks(x, y, 8, true);
    water.disturb(x, y, 10, 50);
    markFirstInteraction();
}

// Tap a shooting star while it is still bright. Too late only gets a faint fizzle.
function tryCatchShootingStar(x, y) {
    if (mode !== "pond" || !cometVisitor) return false;
    if (!shootingStarHitTest(x, y)) return false;
    const c = cometVisitor;
    if (c.t <= (c.catchUntil || 1)) {
        grantShootingStarWish(c.x, c.y);
    } else {
        missShootingStarLate(c.x, c.y);
    }
    return true;
}

function drawCometVisitor(ctx) {
    if (!cometVisitor) return;
    const c = cometVisitor;
    const fadeIn = Math.min(1, c.t * 4);
    const fadeOut = Math.min(1, Math.max(0, (c.life - c.t) * 3.2));
    const u = fadeIn * fadeOut * (c.caught ? (1 - Math.min(1, c.burst || 0)) : 1);
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    ctx.translate(c.x, c.y);
    ctx.rotate(c.dir);
    const trail = 54 + (c.caught ? 20 : 0);
    const g = ctx.createLinearGradient(-trail, 0, 22, 0);
    if (c.caught && c.wishTrail) {
        g.addColorStop(0, "rgba(255,160,80,0)");
        g.addColorStop(0.35, "rgba(255,190,110," + (0.4 * u) + ")");
        g.addColorStop(0.7, "rgba(255,230,170," + (0.8 * u) + ")");
        g.addColorStop(1, "rgba(255,255,245," + (0.98 * u) + ")");
    } else {
        g.addColorStop(0, "rgba(255,180,255,0)");
        g.addColorStop(0.45, "rgba(190,220,255," + (0.35 * u) + ")");
        g.addColorStop(0.82, "rgba(255,240,200," + (0.7 * u) + ")");
        g.addColorStop(1, "rgba(255,255,255," + (0.95 * u) + ")");
    }
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(-trail, 0);
    ctx.quadraticCurveTo(-14, -9, 20, 0);
    ctx.quadraticCurveTo(-14, 9, -trail, 0);
    ctx.fill();
    // Bright head so the catchable tip reads clearly.
    ctx.fillStyle = `rgba(255,255,245,${0.9 * u})`;
    ctx.beginPath();
    ctx.arc(14, 0, 3.2 + (c.caught ? 6 * (c.burst || 0) : 0), 0, Math.PI * 2);
    ctx.fill();
    if (c.caught && c.burst > 0) {
        const b = Math.min(1, c.burst);
        ctx.strokeStyle = `rgba(255,230,180,${0.65 * (1 - b)})`;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(14, 0, 8 + b * 34, 0, Math.PI * 2);
        ctx.stroke();
    }
    ctx.restore();
}

function maybeSpawnIcePatch() {
    if (icePatches.length >= 3) return;
    icePatches.push({
        x: viewW * (0.2 + Math.random() * 0.6),
        y: viewH * (0.2 + Math.random() * 0.6),
        r: 40 + Math.random() * 50,
        age: 0,
        life: 10 + Math.random() * 8,
    });
}

function updateIcePatches(dt) {
    for (let i = icePatches.length - 1; i >= 0; i--) {
        const p = icePatches[i];
        p.age += dt;
        if (p.age >= p.life) {
            icePatches.splice(i, 1);
            continue;
        }
        for (const f of fishes) {
            if (f.dead) continue;
            if (Math.hypot(f.x - p.x, f.y - p.y) < p.r) {
                // Skim: slight speed ease, less turn friction feel via dir hold.
                f.x += Math.cos(f.dir) * 12 * dt;
                f.y += Math.sin(f.dir) * 12 * dt;
            }
        }
    }
}

function drawIcePatches(ctx) {
    if (!icePatches.length) return;
    ctx.save();
    for (const p of icePatches) {
        const u = Math.min(1, p.age * 0.5, (p.life - p.age) * 0.4);
        ctx.fillStyle = "rgba(200,230,245," + (0.1 * u) + ")";
        ctx.strokeStyle = "rgba(230,245,255," + (0.25 * u) + ")";
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.ellipse(p.x, p.y, p.r, p.r * 0.7, 0.2, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
    }
    ctx.restore();
}

function marketCraftNightBloom() {
    // Before moon pond is unlocked: spend rainbow food to open Looks moonlight.
    if (!marketUnlocked) return;
    if (!nightUnlocked) {
        if (availableRainbowFood() < NIGHT_UNLOCK_RAINBOW_COST) return;
        if (!spendRainbowFood(NIGHT_UNLOCK_RAINBOW_COST)) return;
        unlockMoonPond();
        if (Audio.rainbowChime) Audio.rainbowChime(0);
        updateMarketUI();
        markFirstInteraction();
        return;
    }
    if (!spendStashVariants({ platinum: 1, rainbow: 1 })) return;
    beginWeatherMood("fireflies");
    for (let i = 0; i < 3; i++) maybeSpawnIcePatch();
    pendingGlassRain = Math.min(2.8, pendingGlassRain + 0.8);
    if (Audio.goldChime) Audio.goldChime(0);
    updateMarketUI();
    markFirstInteraction();
}

let nightLoop = null; // { t, phase, predator, rewardReady }

function updateHeroSoftJobs(dt) {
    for (const hero of fishes) {
        if (hero.dead || !(hero.isHero || hero.redeemed) || hero.size < 52) continue;
        // Scare smaller wild evils out of the territory ring.
        for (const f of fishes) {
            if (f === hero || f.dead || f.isHero || f.redeemed || f.tamedMonster) continue;
            if (!(f.isPredator || f.isMonster) || f.size >= hero.size * 0.92) continue;
            const d = Math.hypot(f.x - hero.x, f.y - hero.y);
            const r = heroTerritoryRadius(hero) || hero.size * 1.2;
            if (d > r || d < 8) continue;
            const ang = Math.atan2(f.y - hero.y, f.x - hero.x);
            const push = (22 + hero.size * 0.15) * dt * (1 - d / r);
            f.x += Math.cos(ang) * push;
            f.y += Math.sin(ang) * push;
            f.dir += normAngle(ang - f.dir) * Math.min(1, 2.2 * dt);
        }
        // Escort nearby pink breeding pairs: gentle pull toward mid-pair.
        const pinks = fishes.filter((p) => canBreedFish(p) && p !== hero);
        if (pinks.length >= 2) {
            let best = null;
            let bestD = 140;
            for (let i = 0; i < pinks.length; i++) {
                for (let j = i + 1; j < pinks.length; j++) {
                    const mx = (pinks[i].x + pinks[j].x) * 0.5;
                    const my = (pinks[i].y + pinks[j].y) * 0.5;
                    const d = Math.hypot(hero.x - mx, hero.y - my);
                    if (d < bestD) { bestD = d; best = { mx, my }; }
                }
            }
            if (best && bestD > 40) {
                easeToward(hero, best.mx, best.my, dt, 18, 0.55);
            }
        }
        // Calm nearby whirlpools when a large hero parks on them.
        if (typeof whirlpools !== "undefined") {
            for (const w of whirlpools) {
                if (Math.hypot(hero.x - w.x, hero.y - w.y) < hero.size * 0.7 + (w.r || 30)) {
                    w.power = Math.max(8, (w.power || 20) - 18 * dt);
                    w.life = Math.max(0.2, (w.life || 1) - 0.35 * dt);
                }
            }
        }
    }
}

function fuseNearbySpecialFood(dt) {
    // In-pond craft: two special pellets near each other fuse into a recipe effect.
    const specials = foods.filter((f) => !f.eaten && (f.golden || f.rainbow || f.pink
        || f.grower || f.platinum || f.hero));
    if (specials.length < 2) return;
    for (let i = 0; i < specials.length; i++) {
        for (let j = i + 1; j < specials.length; j++) {
            const a = specials[i];
            const b = specials[j];
            if (a.eaten || b.eaten) continue;
            const d = Math.hypot(a.x - b.x, a.y - b.y);
            if (d > (a.radius() + b.radius() + 10)) continue;
            const mx = (a.x + b.x) * 0.5;
            const my = (a.y + b.y) * 0.5;
            let fused = false;
            // gold + pink => mirror twin near mid
            if ((a.golden && b.pink) || (b.golden && a.pink)) {
                const host = fishes.find((f) => !f.dead && !f.isMirror && !f.golden
                    && Math.hypot(f.x - mx, f.y - my) < 160);
                if (host) {
                    const twin = new Fish(host.type);
                    twin.isMirror = true;
                    twin.mirrorOf = assignFishId(host);
                    twin.mirrorTrail = [];
                    twin.size = host.size * 0.92;
                    twin.baseSpeed = host.baseSpeed;
                    twin.x = host.x + Math.cos(host.dir + Math.PI) * 28;
                    twin.y = host.y + Math.sin(host.dir + Math.PI) * 28;
                    twin.dir = host.dir;
                    fishes.push(twin);
                    fused = true;
                }
            } else if ((a.rainbow && b.grower) || (b.rainbow && a.grower)) {
                beginWeatherMood("mist");
                pendingGlassRain = Math.min(2.8, pendingGlassRain + 0.7);
                fused = true;
            } else if ((a.hero && b.pink) || (b.hero && a.pink)) {
                foods.push(new Food(mx, my, 10, { rainbow: true }));
                fused = true;
            }
            if (!fused) continue;
            a.eaten = true;
            b.eaten = true;
            water.disturb(mx, my, 16, 90);
            spawnSplash(mx, my, 10, 0.4);
            if (Audio.goldChime) Audio.goldChime(0);
            return;
        }
    }
}

function updateDebrisTools(dt) {
    // Logs / driftwood gently block wild reptiles; stump-like pots become frog sit spots.
    for (const r of reptiles) {
        if (r.dead || r.tamed || r.isHero || r.golden || r.duelMode) continue;
        for (const o of obstacles) {
            if (!(o.kind === "log" || o.kind === "driftwood" || o.kind === "plank")) continue;
            const d = Math.hypot(r.x - o.x, r.y - o.y);
            const blockR = obstacleRadius(o) + r.size * 0.35;
            if (d >= blockR) continue;
            const ang = Math.atan2(r.y - o.y, r.x - o.x);
            const push = (blockR - d) * 1.4;
            r.x += Math.cos(ang) * push * Math.min(1, 4 * dt);
            r.y += Math.sin(ang) * push * Math.min(1, 4 * dt);
            r.dir += normAngle(ang - r.dir) * Math.min(1, 2 * dt);
        }
    }
    if (!scenery.frogs || !frogGroups.length) return;
    for (const g of frogGroups) {
        const frog = g.frog;
        if (!frog || frog.dead || frog.befriended) continue;
        let best = null;
        let bestD = 90;
        for (const o of obstacles) {
            if (!(o.kind === "stump" || o.kind === "pot" || o.kind === "crate")) continue;
            const d = Math.hypot(frog.x - o.x, frog.y - o.y);
            if (d < bestD) { bestD = d; best = o; }
        }
        if (!best) continue;
        const sitR = (best.r || 18) * 0.35;
        if (bestD > 18) {
            easeToward(frog, best.x, best.y - sitR, dt, 22, 1.1);
        } else {
            frog.kick = 0.08;
            frog.petTimer = Math.max(frog.petTimer || 0, 0.4);
        }
    }
}

function updateNightLoop(dt) {
    if (!nightMode) {
        nightLoop = null;
        return;
    }
    if (!nightLoop) {
        nightLoop = { t: 0, phase: "comet", predator: false, rewardReady: false };
    }
    nightLoop.t += dt;
    if (nightLoop.phase === "comet" && nightLoop.t > 3.2) {
        if (!cometVisitor && Math.random() < 0.72) {
            const side = Math.floor(Math.random() * 4);
            let x, y, tx, ty;
            if (side === 0) { x = -40; y = Math.random() * viewH; tx = viewW + 40; ty = Math.random() * viewH; }
            else if (side === 1) { x = viewW + 40; y = Math.random() * viewH; tx = -40; ty = Math.random() * viewH; }
            else if (side === 2) { x = Math.random() * viewW; y = -40; tx = Math.random() * viewW; ty = viewH + 40; }
            else { x = Math.random() * viewW; y = viewH + 40; tx = Math.random() * viewW; ty = -40; }
            spawnShootingStar(x, y, tx, ty);
        }
        nightLoop.phase = "biolum";
        nightLoop.t = 0;
    } else if (nightLoop.phase === "biolum") {
        // Encourage soft biolum wakes: nudge a few night fish.
        if (Math.random() < 0.08) {
            for (const f of fishes) {
                if (f.dead || !(f.type && f.type.night)) continue;
                if (typeof emitBiolumWake === "function") emitBiolumWake(f);
                break;
            }
        }
        if (nightLoop.t > 8) {
            nightLoop.phase = "predator";
            nightLoop.t = 0;
        }
    } else if (nightLoop.phase === "predator") {
        if (!nightLoop.predator && !swordfish && !octopus && Math.random() < 0.02) {
            nightLoop.predator = true;
            // Prefer swordfish as the rare night loop hunter.
            if (!swordfish || swordfish.dead) {
                swordfish = new Swordfish();
            }
        }
        if (nightLoop.t > 14 || (nightLoop.predator && swordfish && swordfish.dead)) {
            nightLoop.phase = "dawn";
            nightLoop.t = 0;
            nightLoop.rewardReady = true;
        }
    } else if (nightLoop.phase === "dawn") {
        if (nightLoop.rewardReady) {
            nightLoop.rewardReady = false;
            const cx = viewW * 0.5;
            const cy = viewH * 0.5;
            foods.push(new Food(cx + (Math.random() - 0.5) * 40, cy, 11, { rainbow: true }));
            foods.push(new Food(cx + 30, cy + 10, 9, platinumUnlocked ? { platinum: true } : { golden: true }));
            if (Audio.rainbowChime) Audio.rainbowChime(0);
            beginWeatherMood("pollen");
        }
        if (nightLoop.t > 5.5) {
            // Soft return toward day mood without forcing night off.
            nightLoop = { t: 0, phase: "comet", predator: false, rewardReady: false };
        }
    }
}

function updateFlavorSystems(dt) {
    updateColoredWakes(dt);
    updateCurrentLanes(dt);
    updatePetEchoes(dt);
    updateWeather(dt);
    updateGlassCrossover(dt);
    updateGuardianPairs(dt);
    updateBreathBubbles(dt);
    updateSiltClouds(dt);
    updateSonicRings(dt);
    updatePetMemories(dt);
    updateWhirlpools(dt);
    updateSchoolOrbit(dt);
    updateMemorySeek(dt);
    updateHeroSoftJobs(dt);
    fuseNearbySpecialFood(dt);
    updateDebrisTools(dt);
    updateNightLoop(dt);
    maybeSpawnComet(dt);
    updateStarWishSparks(dt);
    updateIcePatches(dt);
    if (weatherMood && weatherMood.kind === "mist" && Math.random() < 0.002) {
        maybeSpawnIcePatch();
    }
    // Spinning debris can birth a soft whirlpool.
    if (Math.random() < 0.01) {
        for (const o of obstacles) {
            if (Math.abs(o.spin || 0) > 1.2) {
                spawnWhirlpool(o.x, o.y, 35 + Math.abs(o.spin) * 8, 4);
                break;
            }
        }
    }
    if (octopus && !octopus.dead && !octopus.golden && Math.random() < 0.004) {
        spawnWhirlpool(octopus.x, octopus.y, 55, 6);
    }
    if (giantEnding) {
        giantBedReveal = Math.min(1, giantBedReveal + dt * 0.22);
        const f = giantEnding.fish;
        if (f && Math.random() < 0.08) emitSiltCloud(f.x, f.y, f.size);
    } else {
        giantBedReveal = Math.max(0, giantBedReveal - dt * 0.5);
    }
}

// ===========================================================================
// WINDOW RHYTHM STUDIO: step loops on glass, save tunes, play soft in pond
// ===========================================================================
const RHYTHM_KEY = "ripple-tunes-v1";
const RHYTHM_STEP_CHOICES = [16, 32, 64];
const RHYTHM_DEFAULT_STEPS = 32;
const RHYTHM_TUNE_CAP = 24;
const RHYTHM_DRUM_LANES = ["kick", "snare", "clap", "hat"];

function clampRhythmSteps(n) {
    const v = +n || RHYTHM_DEFAULT_STEPS;
    if (RHYTHM_STEP_CHOICES.includes(v)) return v;
    // Migrate odd lengths toward nearest supported size.
    if (v <= 16) return 16;
    if (v <= 32) return 32;
    return 64;
}

function getRhythmSteps() {
    return clampRhythmSteps(rhythmPattern && rhythmPattern.steps);
}

function emptyRhythmLane(n) {
    return Array(clampRhythmSteps(n != null ? n : getRhythmSteps())).fill(0);
}

function emptyToneLane(n) {
    return Array(clampRhythmSteps(n != null ? n : getRhythmSteps())).fill(null);
}

function resizeRhythmLane(arr, n, fill) {
    const steps = clampRhythmSteps(n);
    const src = Array.isArray(arr) ? arr : [];
    const out = Array(steps).fill(fill);
    for (let i = 0; i < Math.min(steps, src.length); i++) out[i] = src[i] || fill;
    return out;
}

function resizeToneLane(arr, n) {
    const steps = clampRhythmSteps(n);
    const src = Array.isArray(arr) ? arr : [];
    const out = Array(steps).fill(null);
    for (let i = 0; i < Math.min(steps, src.length); i++) {
        const t = src[i];
        if (t && t.on) {
            out[i] = {
                on: 1,
                freq: +t.freq || 440,
                x: +t.x || 0,
                y: +t.y || 0,
                v: clamp01(t.v == null ? 0.45 : t.v),
            };
        }
    }
    return out;
}

function newRhythmPattern(bpm, steps) {
    const n = clampRhythmSteps(steps != null ? steps : RHYTHM_DEFAULT_STEPS);
    return {
        bpm: Math.max(60, Math.min(160, bpm || 96)),
        steps: n,
        swing: 0,
        gain: 1,
        kick: emptyRhythmLane(n),
        snare: emptyRhythmLane(n),
        clap: emptyRhythmLane(n),
        hat: emptyRhythmLane(n),
        tone: emptyToneLane(n),
    };
}

function cloneRhythmPattern(src) {
    const steps = clampRhythmSteps(src && src.steps != null ? src.steps : RHYTHM_DEFAULT_STEPS);
    const p = newRhythmPattern(src && src.bpm, steps);
    if (!src) return p;
    p.bpm = Math.max(60, Math.min(160, src.bpm || 96));
    p.swing = clamp01(src.swing == null ? 0 : src.swing);
    p.gain = Math.max(0.2, Math.min(1, src.gain == null ? 1 : +src.gain));
    for (const lane of RHYTHM_DRUM_LANES) {
        p[lane] = resizeRhythmLane(src[lane], steps, 0).map((v) => (v ? 1 : 0));
    }
    p.tone = resizeToneLane(src.tone, steps);
    // Fill missing xy on tones from step position.
    for (let i = 0; i < steps; i++) {
        const t = p.tone[i];
        if (!t) continue;
        if (!(t.x > 0 || t.y > 0)) {
            t.x = ((i + 0.5) / steps) * (viewW || 800);
            t.y = (viewH || 600) * 0.4;
        }
    }
    return p;
}

function patternToTunePayload(pattern, name, id) {
    const steps = clampRhythmSteps(pattern.steps);
    return {
        id: id || ("t" + Date.now().toString(36) + Math.floor(Math.random() * 1e4).toString(36)),
        name: (name || "Untitled").slice(0, 28),
        bpm: pattern.bpm,
        steps,
        swing: clamp01(pattern.swing || 0),
        gain: Math.max(0.2, Math.min(1, pattern.gain == null ? 1 : pattern.gain)),
        kick: (pattern.kick || []).slice(0, steps),
        snare: (pattern.snare || []).slice(0, steps),
        clap: (pattern.clap || emptyRhythmLane(steps)).slice(0, steps),
        hat: (pattern.hat || []).slice(0, steps),
        tone: (pattern.tone || []).slice(0, steps).map((t) => (t && t.on ? {
            on: 1, freq: t.freq, x: t.x, y: t.y, v: t.v,
        } : null)),
    };
}

let rhythmPattern = newRhythmPattern(96, RHYTHM_DEFAULT_STEPS);
let rhythmTunes = [];
let rhythmActiveId = null;
let rhythmPlaying = false;
let rhythmRecordArmed = false;
let rhythmPanelOpen = false;
let tunesPanelOpen = false;
let rhythmStep = 0;
let rhythmAcc = 0;
let rhythmPondGain = 0.42; // quieter under pond life
let rhythmPlaySource = null; // "studio" | "pond"
let rhythmLifePulse = 0; // lingering beat energy for pond sway
let rhythmKickTight = 0; // school tighten after kicks
let rhythmMetronome = false;
let rhythmClipboard = null;
let rhythmMute = { kick: false, snare: false, clap: false, hat: false, tone: false };

function loadRhythmStore() {
    rhythmTunes = [];
    rhythmActiveId = null;
    try {
        const raw = localStorage.getItem(RHYTHM_KEY);
        if (!raw) return;
        const data = JSON.parse(raw);
        if (!data || typeof data !== "object") return;
        const list = Array.isArray(data.tunes) ? data.tunes : [];
        for (const row of list) {
            if (!row || typeof row !== "object") continue;
            const tune = patternToTunePayload(cloneRhythmPattern(row), row.name || "Tune", row.id);
            rhythmTunes.push(tune);
            if (rhythmTunes.length >= RHYTHM_TUNE_CAP) break;
        }
        if (data.activeId) {
            const hit = rhythmTunes.find((t) => t.id === data.activeId);
            if (hit) {
                rhythmActiveId = hit.id;
                rhythmPattern = cloneRhythmPattern(hit);
            }
        }
    } catch (err) { /* ignore */ }
}

function saveRhythmStore() {
    try {
        localStorage.setItem(RHYTHM_KEY, JSON.stringify({
            version: 2,
            activeId: rhythmActiveId,
            tunes: rhythmTunes,
        }));
    } catch (err) { /* ignore */ }
}

function rhythmStepSeconds() {
    const bpm = Math.max(60, Math.min(160, rhythmPattern.bpm || 96));
    const base = 60 / bpm / 4; // sixteenth notes
    const swing = clamp01(rhythmPattern.swing || 0);
    // Even steps stretch, odd steps compress (classic swung 16ths).
    const even = (rhythmStep % 2) === 0;
    return base * (1 + (even ? swing : -swing) * 0.55);
}

function updateRhythmStepLabel() {
    const label = document.getElementById("rhythm-step-label");
    if (label) label.textContent = (rhythmStep + 1) + " / " + getRhythmSteps();
}

function setRhythmPlaying(on, source) {
    rhythmPlaying = !!on;
    if (rhythmPlaying) {
        rhythmPlaySource = source || (mode === "pond" ? "pond" : "studio");
        rhythmAcc = 0;
    } else {
        rhythmPlaySource = null;
        rhythmRecordArmed = false;
        updateRhythmRecordUI();
    }
    updateRhythmTransportUI();
    updateTunesPanelUI();
}

function stopRhythmPlayback() {
    setRhythmPlaying(false);
}

function playRhythmStep(stepIndex, visual) {
    const steps = getRhythmSteps();
    const i = ((stepIndex % steps) + steps) % steps;
    const pond = mode === "pond" || rhythmPlaySource === "pond";
    const studioGain = Math.max(0.2, Math.min(1, rhythmPattern.gain == null ? 1 : rhythmPattern.gain));
    const drumGain = (pond ? rhythmPondGain : 1) * studioGain;
    const panKick = -0.15;
    const panSnare = 0.1;
    const panClap = 0.2;
    const panHat = 0.35;
    const kickOn = !rhythmMute.kick && !!rhythmPattern.kick[i];
    const snareOn = !rhythmMute.snare && !!rhythmPattern.snare[i];
    const clapOn = !rhythmMute.clap && !!(rhythmPattern.clap && rhythmPattern.clap[i]);
    const hatOn = !rhythmMute.hat && !!rhythmPattern.hat[i];
    const tone = rhythmPattern.tone[i];
    const toneOn = !rhythmMute.tone && !!(tone && tone.on);
    if (rhythmMetronome && !pond && Audio.playRhythmHit && (i % 4) === 0) {
        Audio.playRhythmHit("click", 0, drumGain * (i === 0 ? 1 : 0.65));
    }
    if (kickOn && Audio.playRhythmHit) {
        Audio.playRhythmHit("kick", panKick, drumGain);
        if (visual && mode === "window") {
            spawnWindowRippleVisual(viewW * 0.22, viewH * 0.78, 0.55);
        }
    }
    if (snareOn && Audio.playRhythmHit) {
        Audio.playRhythmHit("snare", panSnare, drumGain * 0.95);
        if (visual && mode === "window") {
            spawnWindowRippleVisual(viewW * 0.5, viewH * 0.55, 0.4);
        }
    }
    if (clapOn && Audio.playRhythmHit) {
        Audio.playRhythmHit("clap", panClap, drumGain * 0.9);
        if (visual && mode === "window") {
            spawnWindowRippleVisual(viewW * 0.62, viewH * 0.42, 0.34);
        }
    }
    if (hatOn && Audio.playRhythmHit) {
        Audio.playRhythmHit("hat", panHat, drumGain * 0.85);
        if (visual && mode === "window") {
            spawnWindowRippleVisual(viewW * 0.72, viewH * 0.22, 0.28);
        }
    }
    if (toneOn) {
        const x = Math.max(8, Math.min(viewW - 8, tone.x));
        const y = Math.max(8, Math.min(viewH - 8, tone.y));
        const v = clamp01((tone.v == null ? 0.45 : tone.v) * (pond ? 0.7 : 1) * studioGain);
        if (visual && mode === "window") {
            spawnWindowRipple(x, y, v);
        } else {
            // Pond: glass voice without glass ripples.
            const voice = windowPosToVoice(x, y);
            const pan = Math.max(-1, Math.min(1, (x / viewW) * 2 - 1));
            Audio.playDrop({
                freq: tone.freq || voice.freq,
                decay: voice.decay,
                velocity: clamp01(0.22 + v * 0.45),
                pan,
                plunk: voice.plunk,
                surface: "water",
            });
        }
    }
    if (mode === "pond" && rhythmPlaying) {
        pulsePondToRhythm(kickOn, snareOn, hatOn || clapOn, toneOn);
    }
}

// Soft beat reaction: sway, school tighten on kicks, night flicker on hats/tones.
function pulsePondToRhythm(kickOn, snareOn, hatOn, toneOn) {
    if (kickOn) {
        rhythmKickTight = 1;
        rhythmLifePulse = Math.max(rhythmLifePulse, 1);
    } else if (snareOn) {
        rhythmLifePulse = Math.max(rhythmLifePulse, 0.72);
    } else if (hatOn || toneOn) {
        rhythmLifePulse = Math.max(rhythmLifePulse, 0.42);
    }
    if ((hatOn || toneOn) && nightMode && typeof emitBiolumWake === "function") {
        let n = 0;
        for (const f of fishes) {
            if (f.dead || f.golden || !(f.type && f.type.night)) continue;
            emitBiolumWake(f);
            if (++n >= 3) break;
        }
    }
}

function updatePondMusicLife(dt) {
    const playing = rhythmPlaying && mode === "pond";
    const pulseEase = 1 - Math.exp(-(playing ? 2.4 : 3.6) * dt);
    rhythmLifePulse = Math.max(0, rhythmLifePulse - (playing ? 1.35 : 2.4) * dt);
    rhythmKickTight = Math.max(0, rhythmKickTight - (playing ? 1.15 : 2.2) * dt);
    if (!playing || (!fishes.length && !(pacifistVisitors && pacifistVisitors.length))) return;

    const pulse = rhythmLifePulse;
    const tight = rhythmKickTight;
    const cx = viewW * 0.5;
    const cy = viewH * 0.5;
    const tNow = performance.now() * 0.001;

    for (const f of fishes) {
        if (f.dead || f.golden || f.rainbowLeaving || f.insideShark) continue;
        // Tiny beat sway: ease, never teleport.
        if (pulse > 0.04) {
            const wobble = Math.sin(tNow * 7.5 + (f.age || 0) * 5.1 + f.x * 0.01) * pulse;
            f.dir += wobble * 0.9 * dt;
            const boost = Math.min(16 * dt, pulse * 20 * dt);
            f.x += Math.cos(f.dir) * boost;
            f.y += Math.sin(f.dir) * boost;
        }
        // Kick tighten: ease toward nearby schoolmates.
        if (tight > 0.05 && !f.isPredator && !f.isMonster && !f.isRainbow) {
            let sx = 0, sy = 0, n = 0;
            for (const o of fishes) {
                if (o === f || o.dead || o.golden || o.isPredator || o.isMonster) continue;
                const d = Math.hypot(o.x - f.x, o.y - f.y);
                if (d > 8 && d < 130) { sx += o.x; sy += o.y; n++; }
            }
            if (n > 0) {
                const tx = sx / n;
                const ty = sy / n;
                const k = Math.min(1, tight * 1.1 * pulseEase);
                f.x += (tx - f.x) * k * 0.045;
                f.y += (ty - f.y) * k * 0.045;
            }
        }
        // Heroes and tamed friends lean gently toward the pond center on the beat.
        if ((f.isHero || f.redeemed || f.tamedMonster) && pulse > 0.08) {
            const want = Math.atan2(cy - f.y, cx - f.x);
            f.dir += normAngle(want - f.dir) * Math.min(1, 0.7 * pulse * dt);
        }
    }
    if (pacifistVisitors && pacifistVisitors.length) {
        for (const p of pacifistVisitors) {
            if (!p || p.dead || p.golden) continue;
            if (pulse > 0.05) {
                p.dir += Math.sin(tNow * 6.2 + p.x * 0.01) * pulse * 0.55 * dt;
                const boost = Math.min(12 * dt, pulse * 14 * dt);
                p.x += Math.cos(p.dir) * boost;
                p.y += Math.sin(p.dir) * boost;
            }
            if (p.tamed && pulse > 0.08) {
                const want = Math.atan2(cy - p.y, cx - p.x);
                p.dir += normAngle(want - p.dir) * Math.min(1, 0.55 * pulse * dt);
            }
        }
    }
}

function updateRhythmStudio(dt) {
    if (typeof updatePondMusicLife === "function") updatePondMusicLife(dt);
    if (!rhythmPlaying) return;
    rhythmAcc += dt;
    let guard = 0;
    while (guard < 8) {
        const stepDur = rhythmStepSeconds();
        if (rhythmAcc < stepDur) break;
        rhythmAcc -= stepDur;
        playRhythmStep(rhythmStep, true);
        rhythmStep = (rhythmStep + 1) % getRhythmSteps();
        guard++;
        updateRhythmStepLabel();
        highlightRhythmBeat(rhythmStep);
    }
}

function highlightRhythmBeat(step) {
    const grid = document.getElementById("rhythm-grid");
    if (!grid) return;
    grid.querySelectorAll(".rhythm-cell.beat").forEach((el) => el.classList.remove("beat"));
    grid.querySelectorAll('.rhythm-cell[data-step="' + step + '"]').forEach((el) => {
        el.classList.add("beat");
    });
}

function rhythmCaptureTone(x, y, v) {
    if (!rhythmRecordArmed || mode !== "window") return;
    Audio.ensure();
    const voice = windowPosToVoice(x, y);
    const steps = getRhythmSteps();
    const step = rhythmStep % steps;
    rhythmPattern.tone[step] = {
        on: 1,
        freq: voice.freq,
        x: x,
        y: y,
        v: clamp01(v == null ? 0.45 : v),
    };
    if (!rhythmPlaying) {
        rhythmStep = (step + 1) % steps;
    }
    renderRhythmGrid();
    highlightRhythmBeat(rhythmStep);
    updateRhythmStepLabel();
    syncActiveRhythmTune();
}

function clearRhythmPattern() {
    const bpm = rhythmPattern.bpm;
    const steps = getRhythmSteps();
    const swing = rhythmPattern.swing || 0;
    const gain = rhythmPattern.gain == null ? 1 : rhythmPattern.gain;
    rhythmPattern = newRhythmPattern(bpm, steps);
    rhythmPattern.swing = swing;
    rhythmPattern.gain = gain;
    rhythmStep = 0;
    rhythmAcc = 0;
    renderRhythmGrid();
    highlightRhythmBeat(0);
    updateRhythmStepLabel();
    syncActiveRhythmTune();
}

function setRhythmLength(steps) {
    const n = clampRhythmSteps(steps);
    if (n === getRhythmSteps()) {
        updateRhythmLengthUI();
        return;
    }
    rhythmPattern = cloneRhythmPattern({ ...rhythmPattern, steps: n });
    rhythmStep = Math.min(rhythmStep, n - 1);
    rhythmAcc = 0;
    renderRhythmGrid();
    highlightRhythmBeat(rhythmStep);
    updateRhythmStepLabel();
    updateRhythmLengthUI();
    syncActiveRhythmTune();
}

function shiftRhythmPattern(dir) {
    const steps = getRhythmSteps();
    const d = dir < 0 ? -1 : 1;
    const rot = (arr, fill) => {
        const out = arr.slice();
        if (d < 0) {
            const first = out.shift();
            out.push(first == null ? fill : first);
        } else {
            const last = out.pop();
            out.unshift(last == null ? fill : last);
        }
        return out;
    };
    for (const lane of RHYTHM_DRUM_LANES) {
        rhythmPattern[lane] = rot(rhythmPattern[lane] || emptyRhythmLane(steps), 0);
    }
    rhythmPattern.tone = rot(rhythmPattern.tone || emptyToneLane(steps), null);
    renderRhythmGrid();
    highlightRhythmBeat(rhythmStep);
    syncActiveRhythmTune();
}

function copyRhythmPattern() {
    rhythmClipboard = patternToTunePayload(rhythmPattern, "Clipboard");
}

function pasteRhythmPattern() {
    if (!rhythmClipboard) return;
    const nameEl = document.getElementById("rhythm-name");
    const keepName = nameEl ? nameEl.value : "";
    const swing = rhythmPattern.swing;
    const gain = rhythmPattern.gain;
    const steps = getRhythmSteps();
    rhythmPattern = cloneRhythmPattern({
        ...rhythmClipboard,
        steps: rhythmClipboard.steps || steps,
        swing: rhythmClipboard.swing != null ? rhythmClipboard.swing : swing,
        gain: rhythmClipboard.gain != null ? rhythmClipboard.gain : gain,
    });
    syncRhythmControlsFromPattern();
    if (nameEl && keepName) nameEl.value = keepName;
    renderRhythmGrid();
    highlightRhythmBeat(rhythmStep);
    syncActiveRhythmTune();
}

function startBlankRhythmTune() {
    stopRhythmPlayback();
    rhythmActiveId = null;
    rhythmPattern = newRhythmPattern(rhythmPattern.bpm || 96, getRhythmSteps());
    rhythmStep = 0;
    rhythmAcc = 0;
    const nameEl = document.getElementById("rhythm-name");
    if (nameEl) nameEl.value = "";
    syncRhythmControlsFromPattern();
    renderRhythmGrid();
    highlightRhythmBeat(0);
    updateRhythmStepLabel();
    updateRhythmTransportUI();
}

function duplicateRhythmTune() {
    const nameEl = document.getElementById("rhythm-name");
    const base = ((nameEl && nameEl.value.trim()) || "Tune").slice(0, 20);
    const name = (base + " copy").slice(0, 28);
    if (rhythmTunes.length >= RHYTHM_TUNE_CAP) rhythmTunes.shift();
    const next = patternToTunePayload(rhythmPattern, name);
    rhythmTunes.push(next);
    rhythmActiveId = next.id;
    if (nameEl) nameEl.value = name;
    saveRhythmStore();
    renderRhythmLibrary();
    renderTunesLibrary();
}

function syncRhythmControlsFromPattern() {
    const bpmEl = document.getElementById("rhythm-bpm");
    const bpmVal = document.getElementById("rhythm-bpm-val");
    const swingEl = document.getElementById("rhythm-swing");
    const swingVal = document.getElementById("rhythm-swing-val");
    const gainEl = document.getElementById("rhythm-gain");
    const gainVal = document.getElementById("rhythm-gain-val");
    if (bpmEl) bpmEl.value = String(rhythmPattern.bpm);
    if (bpmVal) bpmVal.textContent = String(rhythmPattern.bpm);
    const swingPct = Math.round(clamp01(rhythmPattern.swing || 0) * 100);
    if (swingEl) swingEl.value = String(swingPct);
    if (swingVal) swingVal.textContent = String(swingPct);
    const gainPct = Math.round(Math.max(0.2, Math.min(1, rhythmPattern.gain == null ? 1 : rhythmPattern.gain)) * 100);
    if (gainEl) gainEl.value = String(gainPct);
    if (gainVal) gainVal.textContent = String(gainPct);
    updateRhythmLengthUI();
    updateRhythmMetroUI();
}

function updateRhythmLengthUI() {
    const steps = getRhythmSteps();
    document.querySelectorAll(".rhythm-len").forEach((btn) => {
        const on = +btn.dataset.steps === steps;
        btn.classList.toggle("on", on);
        btn.setAttribute("aria-pressed", on ? "true" : "false");
    });
    const grid = document.getElementById("rhythm-grid");
    if (grid) grid.dataset.steps = String(steps);
}

function updateRhythmMetroUI() {
    const btn = document.getElementById("rhythm-metro");
    if (!btn) return;
    btn.classList.toggle("on", !!rhythmMetronome);
    btn.setAttribute("aria-pressed", rhythmMetronome ? "true" : "false");
}

function syncActiveRhythmTune() {
    if (!rhythmActiveId) return;
    const idx = rhythmTunes.findIndex((t) => t.id === rhythmActiveId);
    if (idx < 0) return;
    const nameEl = document.getElementById("rhythm-name");
    const name = (nameEl && nameEl.value.trim()) || rhythmTunes[idx].name || "Untitled";
    rhythmTunes[idx] = patternToTunePayload(rhythmPattern, name, rhythmActiveId);
    saveRhythmStore();
    renderRhythmLibrary();
    renderTunesLibrary();
}

function toggleRhythmCell(lane, step) {
    const steps = getRhythmSteps();
    if (step < 0 || step >= steps) return;
    if (lane === "tone") {
        if (rhythmPattern.tone[step]) rhythmPattern.tone[step] = null;
        else {
            const x = ((step + 0.5) / steps) * viewW;
            const y = viewH * 0.4;
            const voice = windowPosToVoice(x, y);
            rhythmPattern.tone[step] = { on: 1, freq: voice.freq, x, y, v: 0.42 };
            if (Audio.playDrop) {
                Audio.ensure();
                const pan = Math.max(-1, Math.min(1, (x / viewW) * 2 - 1));
                Audio.playDrop({
                    freq: voice.freq, decay: voice.decay, velocity: 0.4, pan,
                    plunk: voice.plunk, surface: "water",
                });
            }
        }
    } else {
        if (!rhythmPattern[lane]) rhythmPattern[lane] = emptyRhythmLane(steps);
        rhythmPattern[lane][step] = rhythmPattern[lane][step] ? 0 : 1;
        if (rhythmPattern[lane][step] && Audio.playRhythmHit) {
            Audio.ensure();
            Audio.playRhythmHit(lane, 0, 0.9);
        }
    }
    renderRhythmGrid();
    highlightRhythmBeat(rhythmStep);
    syncActiveRhythmTune();
}

function renderRhythmGrid() {
    const grid = document.getElementById("rhythm-grid");
    if (!grid) return;
    const steps = getRhythmSteps();
    grid.dataset.steps = String(steps);
    const lanes = [
        { key: "kick", label: "Kick" },
        { key: "snare", label: "Snare" },
        { key: "clap", label: "Clap" },
        { key: "hat", label: "Hat" },
        { key: "tone", label: "Tone" },
    ];
    grid.innerHTML = "";
    for (const lane of lanes) {
        const lab = document.createElement("button");
        lab.type = "button";
        lab.className = "rhythm-lane-label" + (rhythmMute[lane.key] ? " muted" : "");
        lab.textContent = lane.label;
        lab.title = rhythmMute[lane.key] ? "Unmute " + lane.label : "Mute " + lane.label;
        lab.addEventListener("click", (e) => {
            e.stopPropagation();
            rhythmMute[lane.key] = !rhythmMute[lane.key];
            renderRhythmGrid();
            highlightRhythmBeat(rhythmStep);
        });
        grid.appendChild(lab);
        for (let i = 0; i < steps; i++) {
            const btn = document.createElement("button");
            btn.type = "button";
            btn.className = "rhythm-cell"
                + (lane.key === "tone" ? " tone" : "")
                + (lane.key === "clap" ? " clap" : "")
                + ((i % 4) === 0 ? " bar" : "");
            btn.dataset.lane = lane.key;
            btn.dataset.step = String(i);
            const on = lane.key === "tone"
                ? !!(rhythmPattern.tone[i] && rhythmPattern.tone[i].on)
                : !!(rhythmPattern[lane.key] && rhythmPattern[lane.key][i]);
            if (on) btn.classList.add("on");
            btn.title = lane.label + " step " + (i + 1);
            btn.setAttribute("aria-pressed", on ? "true" : "false");
            btn.addEventListener("click", (e) => {
                e.stopPropagation();
                Audio.ensure();
                toggleRhythmCell(lane.key, i);
            });
            grid.appendChild(btn);
        }
    }
}

function renderRhythmLibrary() {
    const lib = document.getElementById("rhythm-library");
    if (!lib) return;
    lib.innerHTML = "";
    for (const tune of rhythmTunes) {
        const row = document.createElement("div");
        row.className = "rhythm-tune-row";
        const loadBtn = document.createElement("button");
        loadBtn.type = "button";
        loadBtn.className = "market-row";
        loadBtn.textContent = tune.name;
        loadBtn.title = "Load " + tune.name;
        loadBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            loadRhythmTune(tune.id);
        });
        const playBtn = document.createElement("button");
        playBtn.type = "button";
        playBtn.className = "market-row rhythm-mini";
        playBtn.textContent = "Play";
        playBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            loadRhythmTune(tune.id);
            Audio.ensure();
            setRhythmPlaying(true, "studio");
        });
        const delBtn = document.createElement("button");
        delBtn.type = "button";
        delBtn.className = "market-row rhythm-mini rhythm-del";
        delBtn.textContent = "Delete";
        delBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            deleteRhythmTune(tune.id);
        });
        row.appendChild(loadBtn);
        row.appendChild(playBtn);
        row.appendChild(delBtn);
        lib.appendChild(row);
    }
}

function renderTunesLibrary() {
    const lib = document.getElementById("tunes-library");
    const empty = document.getElementById("tunes-empty");
    if (!lib) return;
    lib.innerHTML = "";
    if (!rhythmTunes.length) {
        if (empty) empty.hidden = false;
        return;
    }
    if (empty) empty.hidden = true;
    for (const tune of rhythmTunes) {
        const row = document.createElement("div");
        row.className = "rhythm-tune-row";
        const playBtn = document.createElement("button");
        playBtn.type = "button";
        playBtn.className = "market-row";
        const isThis = rhythmPlaying && rhythmPlaySource === "pond" && rhythmActiveId === tune.id;
        playBtn.textContent = (isThis ? "Playing · " : "") + tune.name;
        playBtn.title = isThis ? "Playing " + tune.name : "Play " + tune.name + " in the pond";
        playBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            Audio.ensure();
            loadRhythmTune(tune.id);
            setRhythmPlaying(true, "pond");
        });
        row.appendChild(playBtn);
        lib.appendChild(row);
    }
}

function loadRhythmTune(id) {
    const tune = rhythmTunes.find((t) => t.id === id);
    if (!tune) return;
    rhythmActiveId = tune.id;
    rhythmPattern = cloneRhythmPattern(tune);
    rhythmStep = 0;
    rhythmAcc = 0;
    const nameEl = document.getElementById("rhythm-name");
    if (nameEl) nameEl.value = tune.name;
    syncRhythmControlsFromPattern();
    renderRhythmGrid();
    highlightRhythmBeat(0);
    updateRhythmStepLabel();
    saveRhythmStore();
    updateRhythmTransportUI();
}

function saveCurrentRhythmTune() {
    const nameEl = document.getElementById("rhythm-name");
    let name = (nameEl && nameEl.value.trim()) || "Untitled";
    name = name.slice(0, 28);
    let tune = rhythmActiveId ? rhythmTunes.find((t) => t.id === rhythmActiveId) : null;
    if (tune) {
        const next = patternToTunePayload(rhythmPattern, name, tune.id);
        const idx = rhythmTunes.findIndex((t) => t.id === tune.id);
        rhythmTunes[idx] = next;
        rhythmActiveId = next.id;
    } else {
        if (rhythmTunes.length >= RHYTHM_TUNE_CAP) rhythmTunes.shift();
        const next = patternToTunePayload(rhythmPattern, name);
        rhythmTunes.push(next);
        rhythmActiveId = next.id;
    }
    if (nameEl) nameEl.value = name;
    saveRhythmStore();
    renderRhythmLibrary();
    renderTunesLibrary();
}

function deleteRhythmTune(id) {
    rhythmTunes = rhythmTunes.filter((t) => t.id !== id);
    if (rhythmActiveId === id) rhythmActiveId = null;
    saveRhythmStore();
    renderRhythmLibrary();
    renderTunesLibrary();
    updateTunesPanelUI();
}

function updateRhythmRecordUI() {
    const btn = document.getElementById("rhythm-record");
    if (!btn) return;
    btn.classList.toggle("on", !!rhythmRecordArmed);
    btn.setAttribute("aria-pressed", rhythmRecordArmed ? "true" : "false");
    btn.textContent = rhythmRecordArmed ? "Recording" : "Record";
}

function updateRhythmTransportUI() {
    const playBtn = document.getElementById("rhythm-play");
    const rhythmBtn = document.getElementById("rhythm-btn");
    if (playBtn) {
        playBtn.classList.toggle("on", !!rhythmPlaying && rhythmPlaySource === "studio");
        playBtn.textContent = (rhythmPlaying && rhythmPlaySource === "studio") ? "Playing" : "Play";
    }
    if (rhythmBtn) {
        rhythmBtn.classList.toggle("on", !!rhythmPanelOpen);
        rhythmBtn.setAttribute("aria-pressed", rhythmPanelOpen ? "true" : "false");
        rhythmBtn.setAttribute("aria-expanded", rhythmPanelOpen ? "true" : "false");
    }
}

function setRhythmPanelOpen(open) {
    rhythmPanelOpen = !!open;
    if (rhythmPanelOpen) setTunesPanelOpen(false);
    const panel = document.getElementById("rhythm-panel");
    if (panel) {
        panel.classList.toggle("open", rhythmPanelOpen);
        panel.setAttribute("aria-hidden", rhythmPanelOpen ? "false" : "true");
    }
    updateRhythmTransportUI();
    if (rhythmPanelOpen) {
        renderRhythmGrid();
        renderRhythmLibrary();
        syncRhythmControlsFromPattern();
        highlightRhythmBeat(rhythmStep);
        updateRhythmStepLabel();
    }
}

function setTunesPanelOpen(open) {
    tunesPanelOpen = !!open;
    if (tunesPanelOpen) {
        setRhythmPanelOpen(false);
        setMarketOpen(false);
        setProgressOpen(false);
        setRegistryOpen(false);
    }
    const panel = document.getElementById("tunes-panel");
    if (panel) {
        panel.classList.toggle("open", tunesPanelOpen);
        panel.setAttribute("aria-hidden", tunesPanelOpen ? "false" : "true");
    }
    updateTunesPanelUI();
    if (tunesPanelOpen) renderTunesLibrary();
}

function updateTunesPanelUI() {
    const btn = document.getElementById("tunes-btn");
    if (btn) {
        btn.classList.toggle("on", !!tunesPanelOpen || (rhythmPlaying && rhythmPlaySource === "pond"));
        btn.setAttribute("aria-pressed", tunesPanelOpen ? "true" : "false");
        btn.setAttribute("aria-expanded", tunesPanelOpen ? "true" : "false");
        btn.title = (rhythmPlaying && rhythmPlaySource === "pond")
            ? "Tunes playing"
            : "Tunes";
    }
    if (tunesPanelOpen) renderTunesLibrary();
}

function onRhythmModeChange() {
    if (mode === "pond") {
        setRhythmPanelOpen(false);
        rhythmRecordArmed = false;
        updateRhythmRecordUI();
        // Keep pond playback running; studio visuals stop with mode.
    } else {
        setTunesPanelOpen(false);
        if (rhythmPlaying && rhythmPlaySource === "pond") {
            rhythmPlaySource = "studio";
        }
    }
    updateRhythmTransportUI();
    updateTunesPanelUI();
}

function initRhythmStudioUI() {
    loadRhythmStore();
    if (!rhythmPattern || !rhythmPattern.steps) {
        rhythmPattern = newRhythmPattern(96, RHYTHM_DEFAULT_STEPS);
    } else {
        rhythmPattern = cloneRhythmPattern(rhythmPattern);
    }
    renderRhythmGrid();
    renderRhythmLibrary();
    renderTunesLibrary();
    syncRhythmControlsFromPattern();
    updateRhythmStepLabel();

    const bpmEl = document.getElementById("rhythm-bpm");
    const bpmVal = document.getElementById("rhythm-bpm-val");
    if (bpmEl) {
        bpmEl.addEventListener("input", (e) => {
            e.stopPropagation();
            rhythmPattern.bpm = Math.max(60, Math.min(160, +bpmEl.value || 96));
            if (bpmVal) bpmVal.textContent = String(rhythmPattern.bpm);
            syncActiveRhythmTune();
        });
        bpmEl.addEventListener("click", (e) => e.stopPropagation());
    }

    const swingEl = document.getElementById("rhythm-swing");
    const swingVal = document.getElementById("rhythm-swing-val");
    if (swingEl) {
        swingEl.addEventListener("input", (e) => {
            e.stopPropagation();
            rhythmPattern.swing = clamp01((+swingEl.value || 0) / 100);
            if (swingVal) swingVal.textContent = String(Math.round(rhythmPattern.swing * 100));
            syncActiveRhythmTune();
        });
        swingEl.addEventListener("click", (e) => e.stopPropagation());
    }

    const gainEl = document.getElementById("rhythm-gain");
    const gainVal = document.getElementById("rhythm-gain-val");
    if (gainEl) {
        gainEl.addEventListener("input", (e) => {
            e.stopPropagation();
            rhythmPattern.gain = Math.max(0.2, Math.min(1, (+gainEl.value || 100) / 100));
            if (gainVal) gainVal.textContent = String(Math.round(rhythmPattern.gain * 100));
            syncActiveRhythmTune();
        });
        gainEl.addEventListener("click", (e) => e.stopPropagation());
    }

    document.querySelectorAll(".rhythm-len").forEach((btn) => {
        btn.addEventListener("click", (e) => {
            e.stopPropagation();
            Audio.ensure();
            setRhythmLength(+btn.dataset.steps || RHYTHM_DEFAULT_STEPS);
        });
    });

    const shiftL = document.getElementById("rhythm-shift-left");
    if (shiftL) {
        shiftL.addEventListener("click", (e) => {
            e.stopPropagation();
            shiftRhythmPattern(-1);
        });
    }
    const shiftR = document.getElementById("rhythm-shift-right");
    if (shiftR) {
        shiftR.addEventListener("click", (e) => {
            e.stopPropagation();
            shiftRhythmPattern(1);
        });
    }
    const copyBtn = document.getElementById("rhythm-copy");
    if (copyBtn) {
        copyBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            copyRhythmPattern();
        });
    }
    const pasteBtn = document.getElementById("rhythm-paste");
    if (pasteBtn) {
        pasteBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            pasteRhythmPattern();
        });
    }
    const newBtn = document.getElementById("rhythm-new");
    if (newBtn) {
        newBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            startBlankRhythmTune();
        });
    }
    const dupBtn = document.getElementById("rhythm-dup");
    if (dupBtn) {
        dupBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            duplicateRhythmTune();
        });
    }
    const metroBtn = document.getElementById("rhythm-metro");
    if (metroBtn) {
        metroBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            rhythmMetronome = !rhythmMetronome;
            updateRhythmMetroUI();
        });
    }

    const rhythmBtn = document.getElementById("rhythm-btn");
    if (rhythmBtn) {
        rhythmBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            Audio.ensure();
            setRhythmPanelOpen(!rhythmPanelOpen);
        });
    }
    const tunesBtn = document.getElementById("tunes-btn");
    if (tunesBtn) {
        tunesBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            Audio.ensure();
            setTunesPanelOpen(!tunesPanelOpen);
        });
    }

    const playBtn = document.getElementById("rhythm-play");
    if (playBtn) {
        playBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            Audio.ensure();
            if (rhythmPlaying && rhythmPlaySource === "studio") stopRhythmPlayback();
            else setRhythmPlaying(true, "studio");
        });
    }
    const stopBtn = document.getElementById("rhythm-stop");
    if (stopBtn) {
        stopBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            stopRhythmPlayback();
            rhythmStep = 0;
            highlightRhythmBeat(0);
            updateRhythmStepLabel();
        });
    }
    const recBtn = document.getElementById("rhythm-record");
    if (recBtn) {
        recBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            Audio.ensure();
            rhythmRecordArmed = !rhythmRecordArmed;
            updateRhythmRecordUI();
        });
    }
    const clearBtn = document.getElementById("rhythm-clear");
    if (clearBtn) {
        clearBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            clearRhythmPattern();
        });
    }
    const saveBtn = document.getElementById("rhythm-save");
    if (saveBtn) {
        saveBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            saveCurrentRhythmTune();
        });
    }
    const nameEl = document.getElementById("rhythm-name");
    if (nameEl) {
        nameEl.addEventListener("click", (e) => e.stopPropagation());
        nameEl.addEventListener("keydown", (e) => e.stopPropagation());
    }
    const tunesStop = document.getElementById("tunes-stop");
    if (tunesStop) {
        tunesStop.addEventListener("click", (e) => {
            e.stopPropagation();
            stopRhythmPlayback();
        });
    }

    const rhythmPanel = document.getElementById("rhythm-panel");
    if (rhythmPanel) {
        rhythmPanel.addEventListener("click", (e) => e.stopPropagation());
        rhythmPanel.onpointerdown = (e) => e.stopPropagation();
    }
    const tunesPanel = document.getElementById("tunes-panel");
    if (tunesPanel) {
        tunesPanel.addEventListener("click", (e) => e.stopPropagation());
        tunesPanel.onpointerdown = (e) => e.stopPropagation();
    }

    updateRhythmRecordUI();
    updateRhythmTransportUI();
    updateTunesPanelUI();
    updateRhythmMetroUI();
}

initRhythmStudioUI();

// ===========================================================================
// RENDER LOOP
// ===========================================================================
let lastFrame = performance.now();
let sceneryTime = 0;

function frame(now) {
    const dt = Math.min(0.05, (now - lastFrame) / 1000);
    lastFrame = now;
    sceneryTime += dt;
    tickGfxQuality(dt);
    if (typeof updateRhythmStudio === "function") updateRhythmStudio(dt);

    if (mode === "pond") {
        sunPhase += dt;
        // One water step is enough on weaker devices; second step only when smooth.
        water.step();
        if (gfxQuality >= 2 && dt < 0.028) water.step();

        // Floor first, caustics on the stones, then translucent water.
        drawPondBed(ctx);
        drawBedCaustics(ctx);
        if (typeof drawMoonBedCaustics === "function") drawMoonBedCaustics(ctx);
        if (typeof drawGiantCausticSpotlight === "function") drawGiantCausticSpotlight(ctx);
        if (typeof drawSiltClouds === "function") drawSiltClouds(ctx);
        if (typeof drawIcePatches === "function") drawIcePatches(ctx);
        water.render(ctx);
        if (typeof drawGiantBedReveal === "function") drawGiantBedReveal(ctx);
        // Floor shadows stay on whenever sky light is casting, even on lower gfx.
        // Draw both contact and creature casts before entities so multiply never
        // paints phantom silhouettes on top of frogs, fish, or debris.
        if (lightCastsFloorShadows()) {
            drawSunContactShadows(ctx);
            drawSunCreatureShadows(ctx);
        }

        // Shore and bank scenery sit under the swimming life.
        drawShoreStones(ctx, dt);
        drawSticks(ctx, dt);
        drawReeds(ctx, sceneryTime, dt);
        drawCattails(ctx, sceneryTime, dt);
        // Frogs and tadpoles swim mid-depth as quiet background life.
        drawFrogGroups(ctx);
        updateObstacles(dt);
        updateSoftMovables(dt);
        drawObstacles(ctx, dt);
        // Green-food plants stay permanently (until refresh).
        drawPondPlants(ctx, sceneryTime, dt);

        updateDroplets(dt);
        updateRainbowTrail(dt);
        updateGoldHold(dt);
        updatePickerHold(dt);
        updateMariachiFiesta(dt);
        if (typeof updateFlavorSystems === "function") updateFlavorSystems(dt);

        // Fish live beneath the surface, so draw them first.
        if (!pondFinaleActive()) {
            for (const fish of fishes) fish.update(dt);
            updateBreeding(dt);
            // Rare mirror twins appear beside ordinary fish.
            if (typeof maybeSpawnMirrorTwin === "function" && Math.random() < 0.0009) {
                const host = fishes.find((f) => !f.dead && !f.isMirror && !f.golden && !f.isRainbow);
                if (host) maybeSpawnMirrorTwin(host);
            }
        }
        if (typeof applyCurrentToEntity === "function") {
            for (const o of obstacles) applyCurrentToEntity(o, dt, 1.1);
            for (const f of foods) applyCurrentToEntity(f, dt, 0.7);
        }
        manageEcosystem(dt); // predators, shark, reptiles, POV / giant / remorse finales
        for (let i = fishes.length - 1; i >= 0; i--) {
            if (fishes[i].dead) fishes.splice(i, 1);
        }
        if (typeof drawTerritoryRings === "function") drawTerritoryRings(ctx);
        if (typeof drawCurrentLanes === "function") drawCurrentLanes(ctx);
        if (typeof drawWhirlpools === "function") drawWhirlpools(ctx);
        if (typeof drawPetMemories === "function") drawPetMemories(ctx);
        if (typeof drawColoredWakes === "function") drawColoredWakes(ctx);
        if (typeof drawGuardianPairs === "function") drawGuardianPairs(ctx);
        if (typeof drawSonicRings === "function") drawSonicRings(ctx);
        if (typeof drawBreathBubbles === "function") drawBreathBubbles(ctx);
        if (typeof drawCometVisitor === "function") drawCometVisitor(ctx);
        if (typeof drawStarWishSparks === "function") drawStarWishSparks(ctx);
        // Draw resting gold first (lakebed), then swimmers above them.
        for (const fish of fishes) {
            if (fish.golden) fish.draw(ctx);
        }
        drawRainbowTrail(ctx);
        for (const fish of fishes) {
            if (!fish.golden) fish.draw(ctx);
        }
        for (const r of reptiles) r.draw(ctx);
        if (swordfish) swordfish.draw(ctx);
        if (octopus) octopus.draw(ctx);
        if (crystalMantle) crystalMantle.draw(ctx);
        if (crystalSerpent) crystalSerpent.draw(ctx);
        if (shark) shark.draw(ctx);
        if (whale) whale.draw(ctx);
        if (typeof drawPacifistVisitors === "function") drawPacifistVisitors(ctx);
        if (typeof drawBiomeGuardians === "function") drawBiomeGuardians(ctx);

        // Surface greens float above the fish.
        drawDuckweed(ctx, sceneryTime, dt);
        drawLeaves(ctx, sceneryTime, dt);
        drawLilies(ctx, sceneryTime, dt);

        // Food floats on top, then rocks in flight above that.
        for (const f of foods) f.update(dt);
        for (let i = foods.length - 1; i >= 0; i--) {
            if (foods[i].eaten) foods.splice(i, 1);
        }
        for (const f of foods) f.draw(ctx);
        drawNetCursor(ctx);
        drawCatcherOverlay(ctx);

        for (const rk of rocks) rk.update(dt);
        for (let i = rocks.length - 1; i >= 0; i--) {
            if (rocks[i].dead) rocks.splice(i, 1);
        }
        for (const rk of rocks) rk.draw(ctx);
        drawDroplets(ctx);
        if (!pondFinaleActive()) drawCharge(ctx);

        // Day sun or night moon wash sits above the pond life.
        drawLightAmbience(ctx);
        if (typeof drawDuskWash === "function") drawDuskWash(ctx);
        if (typeof drawWeather === "function") drawWeather(ctx);
        if (typeof drawGlassRainOverlay === "function") drawGlassRainOverlay(ctx);

        // Vignette for depth.
        ctx.save();
        ctx.globalCompositeOperation = "source-over";
        ctx.fillStyle = vignette;
        ctx.fillRect(0, 0, viewW, viewH);
        ctx.restore();

        // Finales draw on top of everything.
        if (povAttack) drawPovAttack(ctx);
        if (orcaFeastEnding) drawOrcaFeastEnding(ctx);
        if (swordfishSpearEnding) drawSwordfishSpearEnding(ctx);
        if (giantEnding) drawGiantEnding(ctx);
        if (heroRemorseEnding) drawHeroRemorseEnding(ctx);
        if (octopusWhaleFight) drawOctopusWhaleFight(ctx);
        if (crystalApexEnding) drawCrystalApexEnding(ctx);
        if (rainbowNinjaEnding) drawRainbowNinjaEnding(ctx);
    } else {
        ctx.globalCompositeOperation = "source-over";
        ctx.fillStyle = "rgba(7, 10, 15, 0.22)";
        ctx.fillRect(0, 0, viewW, viewH);
        ctx.globalCompositeOperation = "lighter";
        for (const rp of ripples) { rp.update(dt); rp.draw(ctx); }
        drawInterference(ctx);
        for (let i = ripples.length - 1; i >= 0; i--) {
            if (ripples[i].dead) ripples.splice(i, 1);
        }
        ctx.globalCompositeOperation = "source-over";
        drawCharge(ctx);
    }

    requestAnimationFrame(frame);
}

function watchdogFinaleSoftlocks() {
    // Real timer: background tabs cap dt, so RAF alone can stretch finales forever.
    if (rainbowNinjaEnding && finaleOvertime(rainbowNinjaEnding)) {
        updateRainbowNinjaEnding(0.05);
    }
    if (octopusWhaleFight && finaleOvertime(octopusWhaleFight)) {
        updateOctopusWhaleFight(0.05);
    }
    if (crystalApexEnding && finaleOvertime(crystalApexEnding)) {
        updateCrystalApexEnding(0.05);
    }
    if (apexDuel && finaleOvertime(apexDuel)) {
        finishApexDuel();
    }
    if (giantEnding && finaleOvertime(giantEnding)) {
        updateGiantEnding(0.05);
    }
    if (heroRemorseEnding && finaleOvertime(heroRemorseEnding)) {
        updateHeroRemorseEnding(0.05);
    }
    if (orcaFeastEnding && finaleOvertime(orcaFeastEnding)) {
        updateOrcaFeastEnding(0.05);
    }
    if (swordfishSpearEnding && finaleOvertime(swordfishSpearEnding)) {
        updateSwordfishSpearEnding(0.05);
    }
    if (povAttack && finaleOvertime(povAttack)) {
        updatePovAttack(0.05);
    }
    if (frogFinale && finaleOvertime(frogFinale)) {
        updateFrogFinale(0.05);
    }
    if (bullfrogFinale && finaleOvertime(bullfrogFinale)) {
        updateBullfrogFinale(0.05);
    }
    for (const r of reptiles || []) {
        if (r && r.rainbowFinale && finaleOvertime(r.rainbowFinale)) {
            updateRainbowReptileFinale(r, 0.05);
        }
    }
    for (const f of fishes || []) {
        if (!f || !f.rainbowLeaving) continue;
        if ((f._rainbowExitT || 0) >= CONFIG.rainbowExitMaxTime) {
            burstRainbowIntoFood(f);
            continue;
        }
        if (f._rainbowExitWall0 != null
            && (performance.now() - f._rainbowExitWall0) * 0.001 >= finaleMaxSeconds()) {
            burstRainbowIntoFood(f);
        }
    }
}

setInterval(() => {
    try { watchdogFinaleSoftlocks(); } catch (err) { /* ignore */ }
}, 500);

gfxQualityCap = estimateGfxQualityCap();
gfxQuality = gfxQualityCap;
resize();
rebuildScenery();
initFish();
updateGoldCountUI();
requestAnimationFrame(frame);
